fn configured_web_base_url() -> Option<String> {
    if let Ok(value) = env::var("LANTOR_WEB_PUBLIC_URL") {
        let trimmed = value.trim().trim_end_matches('/').to_owned();
        if !trimmed.is_empty() {
            return Some(trimmed);
        }
    }
    let bind = crate::web::resolve_web_bind()?;
    let addr = bind.parse::<SocketAddr>().ok()?;
    let host = match addr.ip() {
        IpAddr::V4(ip) if ip.is_unspecified() => {
            tailscale_web_host().unwrap_or_else(|| "127.0.0.1".to_owned())
        }
        IpAddr::V4(ip) => ip.to_string(),
        IpAddr::V6(ip) if ip.is_unspecified() => {
            tailscale_web_host().unwrap_or_else(|| "[::1]".to_owned())
        }
        IpAddr::V6(ip) => format!("[{ip}]"),
    };
    Some(format!("http://{host}:{}", addr.port()))
}

fn tailscale_web_host() -> Option<String> {
    tailscale_ip_from_command().or_else(tailscale_ip_from_ifconfig)
}

fn tailscale_ip_from_command() -> Option<String> {
    let output = StdCommand::new("tailscale")
        .args(["ip", "-4"])
        .output()
        .ok()?;
    if !output.status.success() {
        return None;
    }
    parse_tailscale_ipv4_from_text(&String::from_utf8_lossy(&output.stdout))
}

fn tailscale_ip_from_ifconfig() -> Option<String> {
    let output = StdCommand::new("ifconfig").output().ok()?;
    if !output.status.success() {
        return None;
    }
    parse_tailscale_ipv4_from_text(&String::from_utf8_lossy(&output.stdout))
}

fn parse_tailscale_ipv4_from_text(text: &str) -> Option<String> {
    text.split(|ch: char| ch.is_ascii_whitespace() || ch == '/')
        .find_map(|token| {
            let token = token.trim_matches(|ch: char| !ch.is_ascii_digit() && ch != '.');
            let IpAddr::V4(ip) = token.parse::<IpAddr>().ok()? else {
                return None;
            };
            let octets = ip.octets();
            if octets[0] == 100 && (64..=127).contains(&octets[1]) {
                Some(ip.to_string())
            } else {
                None
            }
        })
}

fn normalize_external_url(url: &str) -> Option<String> {
    let (scheme, rest) = url.split_once(':')?;
    let scheme = scheme.to_ascii_lowercase();
    match scheme.as_str() {
        "http" | "https" if rest.starts_with("//") => Some(url.to_owned()),
        "mailto" if !rest.is_empty() => Some(url.to_owned()),
        "file" if rest.starts_with("//") => Some(url.to_owned()),
        _ => None,
    }
}

fn strip_local_path_line_suffix(value: &str) -> &str {
    if Path::new(value).exists() {
        return value;
    }

    if let Some((path, line)) = value.rsplit_once(':') {
        if !line.is_empty() && line.chars().all(|c| c.is_ascii_digit()) && Path::new(path).exists()
        {
            return path;
        }
    }

    if let Some((path, line)) = value.rsplit_once("#L") {
        if !line.is_empty() && line.chars().all(|c| c.is_ascii_digit()) && Path::new(path).exists()
        {
            return path;
        }
    }

    value
}

fn normalize_local_path_link(url: &str) -> Option<String> {
    let expanded = expand_home_path(url);
    let without_line_suffix = strip_local_path_line_suffix(&expanded);
    let path = Path::new(without_line_suffix);
    if path.is_absolute() && path.exists() {
        return Some(path.to_string_lossy().to_string());
    }
    None
}

fn normalize_open_link_target(url: &str) -> Option<String> {
    let trimmed = url.trim();
    if trimmed.is_empty() || trimmed.len() > 4096 || trimmed.chars().any(char::is_control) {
        return None;
    }

    normalize_external_url(trimmed).or_else(|| normalize_local_path_link(trimmed))
}

fn open_link_target_with_system(target: &str) -> CommandResult<()> {
    #[cfg(target_os = "macos")]
    let status = StdCommand::new("open")
        .arg(target)
        .status()
        .map_err(to_string)?;

    #[cfg(target_os = "windows")]
    let status = StdCommand::new("cmd")
        .args(["/C", "start", "", target])
        .status()
        .map_err(to_string)?;

    #[cfg(all(unix, not(target_os = "macos")))]
    let status = StdCommand::new("xdg-open")
        .arg(target)
        .status()
        .map_err(to_string)?;

    if status.success() {
        Ok(())
    } else {
        Err(format!("failed to open link target: {status}"))
    }
}

#[tauri::command]
async fn open_external_url(url: String) -> CommandResult<()> {
    let target = normalize_open_link_target(&url).ok_or_else(|| {
        "only http, https, mailto, file, and existing local file links can be opened".to_owned()
    })?;
    tauri::async_runtime::spawn_blocking(move || open_link_target_with_system(&target))
        .await
        .map_err(to_string)?
}

#[cfg(target_os = "macos")]
fn request_microphone_permission_blocking() -> CommandResult<()> {
    use std::sync::mpsc;

    use block2::RcBlock;
    use objc2::runtime::Bool;
    use objc2_av_foundation::{AVAuthorizationStatus, AVCaptureDevice, AVMediaTypeAudio};

    let media_type = unsafe {
        AVMediaTypeAudio.ok_or_else(|| "macOS audio media type is unavailable".to_owned())?
    };
    let status = unsafe { AVCaptureDevice::authorizationStatusForMediaType(media_type) };
    if status == AVAuthorizationStatus::Authorized {
        return Ok(());
    }
    if status == AVAuthorizationStatus::Denied || status == AVAuthorizationStatus::Restricted {
        return Err("Microphone permission is blocked.".to_owned());
    }

    let (sender, receiver) = mpsc::channel();
    let completion = RcBlock::new(move |granted: Bool| {
        let _ = sender.send(granted.as_bool());
    });
    unsafe {
        AVCaptureDevice::requestAccessForMediaType_completionHandler(media_type, &completion);
    }

    match receiver.recv_timeout(Duration::from_secs(120)) {
        Ok(true) => Ok(()),
        Ok(false) => Err("Microphone permission is blocked.".to_owned()),
        Err(_) => Err("Timed out waiting for microphone permission.".to_owned()),
    }
}

#[cfg(not(target_os = "macos"))]
fn request_microphone_permission_blocking() -> CommandResult<()> {
    Err("Native microphone permission is only implemented for macOS.".to_owned())
}

#[tauri::command]
async fn request_microphone_permission() -> CommandResult<()> {
    tauri::async_runtime::spawn_blocking(request_microphone_permission_blocking)
        .await
        .map_err(to_string)?
}

#[cfg(target_os = "macos")]
fn request_speech_recognition_permission_blocking() -> CommandResult<()> {
    use std::sync::mpsc;

    use block2::RcBlock;
    use objc2_speech::{SFSpeechRecognizer, SFSpeechRecognizerAuthorizationStatus};

    let status = unsafe { SFSpeechRecognizer::authorizationStatus() };
    if status == SFSpeechRecognizerAuthorizationStatus::Authorized {
        return Ok(());
    }
    if status == SFSpeechRecognizerAuthorizationStatus::Denied {
        return Err("Speech recognition permission is blocked.".to_owned());
    }
    if status == SFSpeechRecognizerAuthorizationStatus::Restricted {
        return Err("Speech recognition is restricted by system settings.".to_owned());
    }

    let (sender, receiver) = mpsc::channel();
    let completion = RcBlock::new(move |status: SFSpeechRecognizerAuthorizationStatus| {
        let _ = sender.send(status);
    });
    unsafe {
        SFSpeechRecognizer::requestAuthorization(&completion);
    }

    match receiver.recv_timeout(Duration::from_secs(120)) {
        Ok(SFSpeechRecognizerAuthorizationStatus::Authorized) => Ok(()),
        Ok(SFSpeechRecognizerAuthorizationStatus::Denied) => {
            Err("Speech recognition permission is blocked.".to_owned())
        }
        Ok(SFSpeechRecognizerAuthorizationStatus::Restricted) => {
            Err("Speech recognition is restricted by system settings.".to_owned())
        }
        Ok(_) => Err("Speech recognition permission was not granted.".to_owned()),
        Err(_) => Err("Timed out waiting for speech recognition permission.".to_owned()),
    }
}

#[cfg(not(target_os = "macos"))]
fn request_speech_recognition_permission_blocking() -> CommandResult<()> {
    Err("Native speech recognition permission is only implemented for macOS.".to_owned())
}

#[tauri::command]
async fn request_speech_recognition_permission() -> CommandResult<()> {
    tauri::async_runtime::spawn_blocking(request_speech_recognition_permission_blocking)
        .await
        .map_err(to_string)?
}

pub(crate) async fn load_bootstrap(pool: &SqlitePool, db_url: String) -> CommandResult<Bootstrap> {
    let owner_profile = load_owner_profile(pool).await?;
    let channels = load_channels(pool).await?;
    let channel_members = load_channel_members(pool).await?;
    let agents = load_agents(pool).await?;
    let messages = load_initial_messages(pool).await?;
    let thread_activities = load_thread_activities(pool).await?;
    let saved_messages = load_saved_messages(pool).await?;
    let todo_items = load_todo_items(pool).await?;
    let dismissed_inbox_items = load_dismissed_inbox_items(pool).await?;
    let read_inbox_items = load_read_inbox_items(pool).await?;
    let artifacts = load_artifacts(pool).await?;
    let tasks = load_tasks(pool).await?;
    let long_tasks = load_long_tasks(pool).await?;
    let reminders = load_reminders(pool).await?;
    let agent_schedules = load_agent_schedules(pool).await?;
    let agent_runs = load_agent_runs(pool).await?;
    let agent_work_items = load_agent_work_items(pool).await?;
    let call_sessions = load_call_sessions(pool).await?;
    let call_utterances = load_call_utterances(pool).await?;
    let call_dispatches = load_call_dispatches(pool).await?;
    let agent_activities = load_agent_activities(pool).await?;
    let supervisor = load_supervisor_status(pool).await?;
    let launch_agent = launch_agent::load_launch_agent_status()?;

    Ok(Bootstrap {
        db_url,
        web_base_url: configured_web_base_url(),
        owner_profile,
        channels,
        channel_members,
        agents,
        messages,
        thread_activities,
        saved_messages,
        todo_items,
        dismissed_inbox_items,
        read_inbox_items,
        artifacts,
        tasks,
        long_tasks,
        reminders,
        agent_schedules,
        agent_runs,
        agent_work_items,
        call_sessions,
        call_utterances,
        call_dispatches,
        agent_activities,
        supervisor,
        launch_agent,
    })
}

#[tauri::command]
async fn check_runtime(runtime: String) -> CommandResult<RuntimeCheck> {
    check_runtime_in_env(runtime).await
}

pub(crate) async fn check_runtime_in_env(runtime: String) -> CommandResult<RuntimeCheck> {
    let runtime = runtime.trim().to_owned();
    let command = match runtime.as_str() {
        "codex" => "codex",
        "claude" => "claude",
        _ => {
            return Ok(RuntimeCheck {
                runtime,
                command: String::new(),
                available: false,
                detail: "Unknown runtime".to_owned(),
            });
        }
    };

    let script = format!(
        "if command -v {command} >/dev/null 2>&1; then {command} --version 2>&1 | head -n 1; else echo '{command} not found in PATH' >&2; exit 127; fi"
    );
    let output = StdCommand::new("/bin/zsh")
        .arg("-lc")
        .arg(script)
        .stdout(Stdio::piped())
        .stderr(Stdio::piped())
        .output()
        .map_err(to_string)?;

    let stdout = String::from_utf8_lossy(&output.stdout).trim().to_owned();
    let stderr = String::from_utf8_lossy(&output.stderr).trim().to_owned();
    let detail = if !stdout.is_empty() {
        stdout
    } else if !stderr.is_empty() {
        stderr
    } else if output.status.success() {
        format!("{command} found")
    } else {
        format!("{command} unavailable")
    };

    Ok(RuntimeCheck {
        runtime,
        command: command.to_owned(),
        available: output.status.success(),
        detail,
    })
}

