async fn update_channel(
    channel_id: Uuid,
    name: String,
    description: String,
    state: State<'_, AppState>,
) -> CommandResult<()> {
    update_channel_in_pool(&state.pool, channel_id, name, description).await
}

pub(crate) async fn update_channel_in_pool(
    pool: &SqlitePool,
    channel_id: Uuid,
    name: String,
    description: String,
) -> CommandResult<()> {
    let normalized = normalize_channel_name(&name);
    if normalized.is_empty() {
        return Err("channel name is empty".to_owned());
    }

    let kind: Option<String> = sqlx::query_scalar("select kind from channels where id = $1")
        .bind(channel_id)
        .fetch_optional(pool)
        .await
        .map_err(to_string)?;
    match kind.as_deref() {
        Some("dm") => return Err("direct messages cannot be renamed".to_owned()),
        Some(_) => {}
        None => return Err("channel does not exist".to_owned()),
    }
    ensure_channel_name_available(pool, &normalized, Some(channel_id)).await?;

    sqlx::query(
        r#"
        update channels
        set name = $2, description = $3
        where id = $1
        "#,
    )
    .bind(channel_id)
    .bind(normalized)
    .bind(description.trim())
    .execute(pool)
    .await
    .map_err(to_string)?;

    if let Some(channel) = load_channel(pool, channel_id).await? {
        let _ = notify_ui_channel_upsert(pool, &channel, "channel_updated").await;
    } else {
        let _ = notify_ui_refresh(pool, "channel_updated").await;
    }
    Ok(())
}

#[tauri::command]
async fn set_channel_agent_membership(
    channel_id: Uuid,
    agent_id: Uuid,
    member: bool,
    state: State<'_, AppState>,
) -> CommandResult<()> {
    set_channel_agent_membership_in_pool(&state.pool, channel_id, agent_id, member).await
}

pub(crate) async fn set_channel_agent_membership_in_pool(
    pool: &SqlitePool,
    channel_id: Uuid,
    agent_id: Uuid,
    member: bool,
) -> CommandResult<()> {
    let channel_row = sqlx::query("select name, kind from channels where id = $1")
        .bind(channel_id)
        .fetch_optional(pool)
        .await
        .map_err(to_string)?;
    let Some(channel_row) = channel_row else {
        return Err("channel does not exist".to_owned());
    };
    let channel_name: String = channel_row.get("name");
    let channel_kind: String = channel_row.get("kind");
    if channel_kind == "dm" {
        return Err("direct message membership is fixed".to_owned());
    }

    let agent_handle: Option<String> =
        sqlx::query_scalar("select handle from agents where id = $1")
            .bind(agent_id)
            .fetch_optional(pool)
            .await
            .map_err(to_string)?;
    if agent_handle.is_none() {
        return Err("agent does not exist".to_owned());
    }

    if member {
        let result = sqlx::query(
            r#"
            insert into channel_members (channel_id, agent_id)
            values ($1, $2)
            on conflict (channel_id, agent_id) do nothing
            "#,
        )
        .bind(channel_id)
        .bind(agent_id)
        .execute(pool)
        .await
        .map_err(to_string)?;
        if result.rows_affected() > 0 {
            if let Some(channel_member) = load_channel_member(pool, channel_id, agent_id).await? {
                let _ = notify_ui_channel_member_upsert(
                    pool,
                    &channel_member,
                    "channel_membership_updated",
                )
                .await;
            }
        }
    } else {
        let result =
            sqlx::query("delete from channel_members where channel_id = $1 and agent_id = $2")
                .bind(channel_id)
                .bind(agent_id)
                .execute(pool)
                .await
                .map_err(to_string)?;
        if result.rows_affected() > 0 {
            let _ = notify_ui_channel_member_delete(
                pool,
                channel_id,
                agent_id,
                "channel_membership_updated",
            )
            .await;
        }
    }

    record_agent_activity(
        pool,
        Some(agent_id),
        None,
        "membership",
        if member {
            "Agent joined channel"
        } else {
            "Agent left channel"
        },
        format!("#{channel_name}"),
    )
    .await?;

    Ok(())
}

