#[tauri::command]
async fn claim_task(
    task_id: Uuid,
    agent_id: Option<Uuid>,
    expected_version: Option<i64>,
    state: State<'_, AppState>,
) -> CommandResult<()> {
    claim_task_in_pool(&state.pool, task_id, agent_id, expected_version).await
}

pub(crate) async fn claim_task_in_pool(
    pool: &SqlitePool,
    task_id: Uuid,
    agent_id: Option<Uuid>,
    expected_version: Option<i64>,
) -> CommandResult<()> {
    let current_status: Option<String> =
        sqlx::query_scalar("select status from tasks where id = $1")
            .bind(task_id)
            .fetch_optional(pool)
            .await
            .map_err(to_string)?;
    let current_status = current_status.ok_or_else(|| "task does not exist".to_owned())?;
    if current_status == "done" {
        return Err("done tasks cannot be reassigned".to_owned());
    }
    if let Some(agent_id) = agent_id {
        let agent_handle = resolve_agent_handle(pool, agent_id)
            .await
            .unwrap_or_else(|_| "unknown".to_owned());
        if !agent_accepts_new_work(pool, agent_id).await? {
            return Err(format!(
                "agent @{agent_handle} is in error state and cannot accept new work"
            ));
        }
    }

    if let (Some(agent_id), Some(expected_version)) = (agent_id, expected_version) {
        return try_claim_unassigned_task(
            pool,
            task_id,
            agent_id,
            Some(expected_version),
            "manual_claim",
        )
        .await?
        .map(|_| ())
        .ok_or_else(|| "task was already claimed or is no longer available".to_owned());
    }

    sqlx::query_scalar::<_, Uuid>(
        r#"
        update tasks
        set assignee_agent_id = $2,
            status = case when $2 is null then status else 'in_progress' end,
            version = version + 1,
            updated_at = strftime('%Y-%m-%dT%H:%M:%f+00:00','now')
        where id = $1
        returning id
        "#,
    )
    .bind(task_id)
    .bind(agent_id)
    .fetch_optional(pool)
    .await
    .map_err(to_string)?
    .ok_or_else(|| "task does not exist".to_owned())?;

    if let Some(agent_id) = agent_id {
        dispatch_task_assignment_to_agent(pool, task_id, agent_id, "manual_claim").await?;
    } else {
        record_agent_activity(
            pool,
            None,
            None,
            "task",
            "Task unassigned",
            json!({ "task_id": task_id }).to_string(),
        )
        .await?;
    }

    let _ = notify_ui_refresh(pool, "task_claimed").await;
    Ok(())
}

#[tauri::command]
async fn forward_task(
    task_id: Uuid,
    target_agent_id: Uuid,
    interrupt_current: bool,
    reason: Option<String>,
    state: State<'_, AppState>,
) -> CommandResult<()> {
    forward_task_in_pool(
        &state.pool,
        task_id,
        target_agent_id,
        interrupt_current,
        reason,
    )
    .await
}

pub(crate) async fn forward_task_in_pool(
    pool: &SqlitePool,
    task_id: Uuid,
    target_agent_id: Uuid,
    interrupt_current: bool,
    reason: Option<String>,
) -> CommandResult<()> {
    let row = sqlx::query(
        r#"
        select t.number, t.title, t.channel_id, t.message_id, t.status, t.assignee_agent_id
        from tasks t
        where t.id = $1
        "#,
    )
    .bind(task_id)
    .fetch_optional(pool)
    .await
    .map_err(to_string)?
    .ok_or_else(|| "task does not exist".to_owned())?;
    let task_number: i64 = row.get("number");
    let title: String = row.get("title");
    let channel_id: Uuid = row.get("channel_id");
    let thread_root_id: Uuid = row.get("message_id");
    let status: String = row.get("status");
    let previous_agent_id: Option<Uuid> = row.get("assignee_agent_id");

    if status == "done" {
        return Err("done tasks cannot be forwarded".to_owned());
    }
    if previous_agent_id == Some(target_agent_id) {
        return Err("task is already assigned to the target agent".to_owned());
    }

    let target_handle = resolve_agent_handle(pool, target_agent_id).await?;
    if !agent_accepts_new_work(pool, target_agent_id).await? {
        return Err(format!(
            "agent @{target_handle} is in error state and cannot accept new work"
        ));
    }
    let previous_handle = match previous_agent_id {
        Some(agent_id) => Some(resolve_agent_handle(pool, agent_id).await?),
        None => None,
    };
    let reason = reason
        .as_deref()
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .unwrap_or("manual_forward")
        .to_owned();

    let queued_work_item_ids = if let Some(previous_agent_id) = previous_agent_id {
        let has_running_work_item: bool = sqlx::query_scalar(
            r#"
            select exists (
                select 1
                from agent_work_items
                where task_id = $1
                  and agent_id = $2
                  and status in ('running', 'cancelling')
            )
            "#,
        )
        .bind(task_id)
        .bind(previous_agent_id)
        .fetch_one(pool)
        .await
        .map_err(to_string)?;
        if has_running_work_item {
            return Err(
                "running tasks cannot be forwarded; wait for the run to finish or stop it first"
                    .to_owned(),
            );
        }
        let queued_work_item_ids = sqlx::query_scalar::<_, Uuid>(
            r#"
            select id
            from agent_work_items
            where task_id = $1
              and agent_id = $2
              and status = 'queued'
            order by created_at asc
            "#,
        )
        .bind(task_id)
        .bind(previous_agent_id)
        .fetch_all(pool)
        .await
        .map_err(to_string)?;
        if queued_work_item_ids.is_empty() {
            return Err("only queued task work items can be forwarded".to_owned());
        }
        queued_work_item_ids
    } else {
        Vec::new()
    };

    sqlx::query_scalar::<_, Uuid>(
        r#"
        update tasks
        set assignee_agent_id = $2,
            status = 'in_progress',
            version = version + 1,
            updated_at = strftime('%Y-%m-%dT%H:%M:%f+00:00','now')
        where id = $1
        returning id
        "#,
    )
    .bind(task_id)
    .bind(target_agent_id)
    .fetch_optional(pool)
    .await
    .map_err(to_string)?
    .ok_or_else(|| "task does not exist".to_owned())?;

    for work_item_id in &queued_work_item_ids {
        cancel_agent_work_in_pool(pool, *work_item_id).await?;
    }

    dispatch_task_assignment_to_agent(pool, task_id, target_agent_id, &reason).await?;
    let from_label = previous_handle
        .as_deref()
        .map(|handle| format!("@{handle}"))
        .unwrap_or_else(|| "unassigned".to_owned());
    insert_system_message(
        pool,
        channel_id,
        Some(thread_root_id),
        format!("Task #{task_number} forwarded from {from_label} to @{target_handle}: {reason}"),
    )
    .await?;
    record_agent_activity(
        pool,
        None,
        None,
        "task",
        format!("Task #{task_number} forwarded"),
        json!({
            "task_id": task_id,
            "title": title,
            "from_agent_id": previous_agent_id,
            "from_agent": previous_handle.map(|handle| format!("@{handle}")),
            "target_agent_id": target_agent_id,
            "target_agent": format!("@{target_handle}"),
            "reason": reason,
            "interrupt_current_requested": interrupt_current,
            "cancelled_queued_work_items": queued_work_item_ids,
        })
        .to_string(),
    )
    .await?;
    let _ = notify_ui_refresh(pool, "task_forwarded").await;
    Ok(())
}

