fn parse_due_at(value: &str) -> CommandResult<DateTime<Utc>> {
    DateTime::parse_from_rfc3339(value)
        .map(|value| value.with_timezone(&Utc))
        .map_err(|err| format!("invalid reminder due_at: {err}"))
}

fn parse_reminder_interval_minutes(value: &str) -> Option<i64> {
    let mut recurrence = value.trim().to_ascii_lowercase();
    if recurrence.is_empty() {
        return None;
    }
    for prefix in ["every:", "interval:", "every "] {
        if let Some(stripped) = recurrence.strip_prefix(prefix) {
            recurrence = stripped.trim().to_owned();
            break;
        }
    }
    if recurrence == "hourly" {
        return Some(60);
    }
    let compact: String = recurrence
        .chars()
        .filter(|ch| !ch.is_ascii_whitespace() && *ch != '_')
        .collect();
    for (suffix, multiplier) in [
        ("minutes", 1),
        ("minute", 1),
        ("mins", 1),
        ("min", 1),
        ("m", 1),
        ("hours", 60),
        ("hour", 60),
        ("hrs", 60),
        ("hr", 60),
        ("h", 60),
    ] {
        if let Some(amount) = compact.strip_suffix(suffix) {
            let amount = amount.parse::<i64>().ok()?;
            let minutes = amount.checked_mul(multiplier)?;
            if (1..=10_080).contains(&minutes) {
                return Some(minutes);
            }
            return None;
        }
    }
    None
}

fn next_reminder_due_at(recurrence: &str, now: DateTime<Utc>) -> Option<DateTime<Utc>> {
    match recurrence.trim() {
        "daily" => Some(now + chrono::Duration::days(1)),
        "weekly" => Some(now + chrono::Duration::weeks(1)),
        "none" => None,
        other => parse_reminder_interval_minutes(other)
            .map(|minutes| now + chrono::Duration::minutes(minutes)),
    }
}

fn normalize_recurrence(value: &str) -> CommandResult<String> {
    let recurrence = value.trim().to_ascii_lowercase();
    if matches!(recurrence.as_str(), "none" | "daily" | "weekly") {
        Ok(recurrence)
    } else if matches!(recurrence.as_str(), "one_shot" | "one-shot" | "once") {
        Ok("none".to_owned())
    } else if let Some(minutes) = parse_reminder_interval_minutes(&recurrence) {
        Ok(format!("every:{minutes}m"))
    } else {
        Err(format!("unsupported reminder recurrence: {recurrence}"))
    }
}

fn normalize_schedule_cadence(value: &str) -> CommandResult<String> {
    let cadence = value.trim();
    if matches!(cadence, "hourly" | "daily" | "weekly") {
        Ok(cadence.to_owned())
    } else {
        Err(format!("unsupported schedule cadence: {cadence}"))
    }
}

async fn insert_reminder_event(
    pool: &SqlitePool,
    reminder_id: Uuid,
    event_type: &str,
    detail: impl AsRef<str>,
) -> CommandResult<()> {
    sqlx::query(
        r#"
        insert into reminder_events (reminder_id, event_type, detail)
        values ($1, $2, $3)
        "#,
    )
    .bind(reminder_id)
    .bind(event_type)
    .bind(detail.as_ref())
    .execute(pool)
    .await
    .map_err(to_string)?;
    Ok(())
}

async fn create_reminder_in_pool(
    pool: &SqlitePool,
    creator_agent_id: Option<Uuid>,
    channel_id: Option<Uuid>,
    thread_root_id: Option<Uuid>,
    message_id: Option<Uuid>,
    title: &str,
    note: &str,
    due_at: DateTime<Utc>,
    recurrence: &str,
) -> CommandResult<Uuid> {
    let title = title.trim();
    if title.is_empty() {
        return Err("reminder title is empty".to_owned());
    }
    let recurrence = normalize_recurrence(recurrence)?;

    if let Some(thread_root_id) = thread_root_id {
        let exists: bool = sqlx::query_scalar(
            "select exists(select 1 from messages where id = $1 and thread_root_id is null)",
        )
        .bind(thread_root_id)
        .fetch_one(pool)
        .await
        .map_err(to_string)?;
        if !exists {
            return Err("thread root does not exist".to_owned());
        }
    }

    let reminder_id: Uuid = sqlx::query_scalar(
        r#"
        insert into reminders (
            channel_id, creator_agent_id, thread_root_id, message_id, title, note, due_at, recurrence, status
        )
        values ($1, $2, $3, $4, $5, $6, $7, $8, 'scheduled')
        returning id
        "#,
    )
    .bind(channel_id)
    .bind(creator_agent_id)
    .bind(thread_root_id)
    .bind(message_id)
    .bind(title)
    .bind(note.trim())
    .bind(due_at)
    .bind(&recurrence)
    .fetch_one(pool)
    .await
    .map_err(to_string)?;
    insert_reminder_event(pool, reminder_id, "created", due_at.to_rfc3339()).await?;
    let _ = notify_ui_refresh(pool, "reminder_created").await;
    Ok(reminder_id)
}

async fn cancel_reminder_in_pool(pool: &SqlitePool, reminder_id: Uuid) -> CommandResult<()> {
    let affected = sqlx::query(
        r#"
        update reminders
        set status = 'cancelled',
            completed_at = strftime('%Y-%m-%dT%H:%M:%f+00:00','now'),
            updated_at = strftime('%Y-%m-%dT%H:%M:%f+00:00','now')
        where id = $1 and status in ('scheduled', 'fired')
        "#,
    )
    .bind(reminder_id)
    .execute(pool)
    .await
    .map_err(to_string)?
    .rows_affected();
    if affected == 0 {
        return Err("reminder does not exist or is not active".to_owned());
    }
    insert_reminder_event(pool, reminder_id, "cancelled", "").await?;
    let _ = notify_ui_refresh(pool, "reminder_cancelled").await;
    Ok(())
}

#[tauri::command]
async fn create_reminder(
    channel_id: Option<Uuid>,
    thread_root_id: Option<Uuid>,
    message_id: Option<Uuid>,
    title: String,
    note: String,
    due_at: String,
    recurrence: String,
    state: State<'_, AppState>,
) -> CommandResult<Uuid> {
    let due_at = parse_due_at(&due_at)?;
    create_reminder_in_pool(
        &state.pool,
        None,
        channel_id,
        thread_root_id,
        message_id,
        &title,
        &note,
        due_at,
        &recurrence,
    )
    .await
}

#[tauri::command]
async fn snooze_reminder(
    reminder_id: Uuid,
    minutes: i64,
    state: State<'_, AppState>,
) -> CommandResult<()> {
    if !(1..=10_080).contains(&minutes) {
        return Err("snooze minutes must be between 1 and 10080".to_owned());
    }
    sqlx::query(
        r#"
        update reminders
        set status = 'scheduled',
            due_at = strftime('%Y-%m-%dT%H:%M:%f+00:00','now','+' || $2 || ' minutes'),
            updated_at = strftime('%Y-%m-%dT%H:%M:%f+00:00','now')
        where id = $1 and status in ('scheduled', 'fired')
        "#,
    )
    .bind(reminder_id)
    .bind(minutes)
    .execute(&state.pool)
    .await
    .map_err(to_string)?;
    insert_reminder_event(
        &state.pool,
        reminder_id,
        "snoozed",
        format!("{minutes} minutes"),
    )
    .await?;
    let _ = notify_ui_refresh(&state.pool, "reminder_snoozed").await;
    Ok(())
}

