fn backend_visible_message_sql(message_alias: &str) -> String {
    let uuid_stream_key_glob = format!(
        "{}-{}-{}-{}-{}",
        "[0-9a-f]".repeat(8),
        "[0-9a-f]".repeat(4),
        "[0-9a-f]".repeat(4),
        "[0-9a-f]".repeat(4),
        "[0-9a-f]".repeat(12)
    );
    let uuid_pending_stream_key_glob = format!("{uuid_stream_key_glob}:pending");
    let run_id_sql = uuid_blob_to_text_sql("ar.id");
    let work_item_id_sql = uuid_blob_to_text_sql("w.id");
    format!(
        r#"
        not (
            {message_alias}.sender_role not in ('owner', 'system')
            and {message_alias}.delivery_state in ('streaming', 'complete')
            and (
                lower({message_alias}.stream_key) glob '{uuid_stream_key_glob}'
                or lower({message_alias}.stream_key) glob '{uuid_stream_key_glob}:*'
            )
            and lower({message_alias}.stream_key) not glob '{uuid_pending_stream_key_glob}'
            and trim({message_alias}.body) = ''
            and not exists (
                select 1 from message_attachments ma
                where ma.message_id = {message_alias}.id
            )
            and not exists (
                select 1 from artifacts ar
                where ar.message_id = {message_alias}.id
            )
        )
        and not (
            {message_alias}.sender_role not in ('owner', 'system')
            and {message_alias}.delivery_state in ('streaming', 'complete')
            and lower(substr({message_alias}.stream_key, 1, 36)) in (
                select {run_id_sql}
                from agent_runs ar
                join agent_work_items w on w.id = ar.work_item_id
                where w.call_dispatch_id is not null
                union
                select {work_item_id_sql}
                from agent_work_items w
                where w.call_dispatch_id is not null
            )
        )
        "#
    )
}

fn uuid_blob_to_text_sql(blob_expr: &str) -> String {
    format!(
        "lower(substr(hex({blob_expr}), 1, 8) || '-' || substr(hex({blob_expr}), 9, 4) || '-' || substr(hex({blob_expr}), 13, 4) || '-' || substr(hex({blob_expr}), 17, 4) || '-' || substr(hex({blob_expr}), 21, 12))"
    )
}

async fn load_channels(pool: &SqlitePool) -> CommandResult<Vec<Channel>> {
    let visible_message_sql = backend_visible_message_sql("m");
    let rows = sqlx::query(&format!(
        r#"
        select
            c.id,
            c.name,
            c.description,
            c.kind,
            c.dm_agent_id,
            cast(count(m.id) filter (
                where julianday(m.created_at) > julianday(
                    coalesce(r.last_read_at, '0001-01-01T00:00:00+00:00')
                )
                  and m.sender_role <> 'owner'
                  and {visible_message_sql}
            ) as integer) as unread_count
        from channels c
        left join channel_read_state r on r.channel_id = c.id
        left join messages m on m.channel_id = c.id
        where c.kind <> 'voice'
        group by c.id, c.name, c.description, c.kind, c.dm_agent_id
        order by
          case
            when c.kind = 'channel' and c.name = 'lantor' then 0
            when c.kind = 'channel' then 1
            else 2
          end,
          c.name
        "#
    ))
    .fetch_all(pool)
    .await
    .map_err(to_string)?;

    Ok(rows
        .into_iter()
        .map(|row| Channel {
            id: row.get("id"),
            name: row.get("name"),
            description: row.get("description"),
            kind: row.get("kind"),
            dm_agent_id: row.get("dm_agent_id"),
            unread_count: row.get("unread_count"),
        })
        .collect())
}

