async fn load_messages(pool: &SqlitePool) -> CommandResult<Vec<Message>> {
    let visible_message_sql = backend_visible_message_sql("m");
    let rows = sqlx::query(&format!(
        r#"
        select
            m.id,
            m.channel_id,
            m.thread_root_id,
            m.sender_agent_id,
            m.sender_name,
            m.sender_role,
            m.body,
            m.is_task,
            m.thread_followed,
            m.delivery_state,
            m.stream_key,
            t.number as task_number,
            t.status as task_status,
            m.created_at,
            m.updated_at
        from messages m
        left join tasks t on t.message_id = m.id
        where {visible_message_sql}
        order by julianday(m.created_at) asc, m.created_at asc
        "#,
    ))
    .fetch_all(pool)
    .await
    .map_err(to_string)?;

    let mut messages: Vec<Message> = rows.iter().map(message_from_row).collect();
    attach_message_attachments(pool, &mut messages).await?;
    attach_message_artifacts(pool, &mut messages).await?;
    Ok(messages)
}

async fn load_initial_messages(pool: &SqlitePool) -> CommandResult<Vec<Message>> {
    load_initial_messages_limited(pool, INITIAL_BOOTSTRAP_MESSAGE_LIMIT).await
}

async fn load_initial_messages_limited(
    pool: &SqlitePool,
    limit: i64,
) -> CommandResult<Vec<Message>> {
    let visible_message_sql = backend_visible_message_sql("m");
    let rows = sqlx::query(&format!(
        r#"
        select *
        from (
            select
                m.id,
                m.channel_id,
                m.thread_root_id,
                m.sender_agent_id,
                m.sender_name,
                m.sender_role,
                m.body,
                m.is_task,
                m.thread_followed,
                m.delivery_state,
                m.stream_key,
                t.number as task_number,
                t.status as task_status,
                m.created_at,
                m.updated_at
            from messages m
            left join tasks t on t.message_id = m.id
            where {visible_message_sql}
            order by julianday(m.created_at) desc, m.created_at desc
            limit $1
        ) recent
        order by julianday(created_at) asc, created_at asc
        "#,
    ))
    .bind(limit)
    .fetch_all(pool)
    .await
    .map_err(to_string)?;

    let mut messages: Vec<Message> = rows.iter().map(message_from_row).collect();
    attach_message_attachments(pool, &mut messages).await?;
    attach_message_artifacts(pool, &mut messages).await?;
    Ok(messages)
}

fn normalized_fetch_messages_limit(limit: Option<i64>) -> i64 {
    limit
        .unwrap_or(DEFAULT_FETCH_MESSAGES_LIMIT)
        .clamp(1, MAX_FETCH_MESSAGES_LIMIT)
}

pub(crate) async fn fetch_messages_in_pool(
    pool: &SqlitePool,
    request: FetchMessagesRequest,
) -> CommandResult<Vec<Message>> {
    let limit = normalized_fetch_messages_limit(request.limit);
    let visible_message_sql = backend_visible_message_sql("m");
    let mut messages = if let Some(thread_root_id) = request.thread_root_id {
        let rows = sqlx::query(&format!(
            r#"
            select *
            from (
                select
                    m.id,
                    m.channel_id,
                    m.thread_root_id,
                    m.sender_agent_id,
                    m.sender_name,
                    m.sender_role,
                    m.body,
                    m.is_task,
                    m.thread_followed,
                    m.delivery_state,
                    m.stream_key,
                    t.number as task_number,
                    t.status as task_status,
                    m.created_at,
                    m.updated_at
                from messages m
                left join tasks t on t.message_id = m.id
                where (m.id = $1 or m.thread_root_id = $1)
                  and {visible_message_sql}
                order by julianday(m.created_at) desc, m.created_at desc
                limit $2
            ) recent
            order by julianday(created_at) asc, created_at asc
            "#,
        ))
        .bind(thread_root_id)
        .bind(limit)
        .fetch_all(pool)
        .await
        .map_err(to_string)?;
        rows.iter().map(message_from_row).collect::<Vec<_>>()
    } else if let Some(channel_id) = request.channel_id {
        let before = request.before.unwrap_or_else(Utc::now);
        let root_filter_sql = if request.root_only.unwrap_or(false) {
            "and m.thread_root_id is null"
        } else {
            ""
        };
        let rows = sqlx::query(&format!(
            r#"
            select *
            from (
                select
                    m.id,
                    m.channel_id,
                    m.thread_root_id,
                    m.sender_agent_id,
                    m.sender_name,
                    m.sender_role,
                    m.body,
                    m.is_task,
                    m.thread_followed,
                    m.delivery_state,
                    m.stream_key,
                    t.number as task_number,
                    t.status as task_status,
                    m.created_at,
                    m.updated_at
                from messages m
                left join tasks t on t.message_id = m.id
                where m.channel_id = $1
                  and julianday(m.created_at) < julianday($2)
                  {root_filter_sql}
                  and {visible_message_sql}
                order by julianday(m.created_at) desc, m.created_at desc
                limit $3
            ) recent
            order by julianday(created_at) asc, created_at asc
            "#,
        ))
        .bind(channel_id)
        .bind(before)
        .bind(limit)
        .fetch_all(pool)
        .await
        .map_err(to_string)?;
        rows.iter().map(message_from_row).collect::<Vec<_>>()
    } else {
        load_initial_messages_limited(pool, limit).await?
    };
    attach_message_attachments(pool, &mut messages).await?;
    attach_message_artifacts(pool, &mut messages).await?;
    Ok(messages)
}

