async fn append_streaming_agent_message_inner(
    pool: &SqlitePool,
    agent_id: Uuid,
    channel_id: Uuid,
    thread_root_id: Option<Uuid>,
    stream_key: &str,
    delta: &str,
    complete_on_truncation: bool,
) -> CommandResult<Uuid> {
    if stream_key.trim().is_empty() {
        return Err("stream_key is empty".to_owned());
    }
    if output_buffer_exists(pool, stream_key).await? {
        if let Some((control_agent_id, run_id, work_item_id)) =
            load_streaming_control_context(pool, stream_key).await?
        {
            return hold_streaming_public_output(
                pool,
                control_agent_id,
                run_id,
                work_item_id,
                channel_id,
                thread_root_id,
                stream_key,
                delta,
                false,
                PublishDecision::HoldStale {
                    base_version: 0,
                    current_version: 0,
                },
            )
            .await;
        }
    }
    if delta.is_empty() {
        return ensure_streaming_agent_message(
            pool,
            agent_id,
            channel_id,
            thread_root_id,
            stream_key,
        )
        .await;
    }

    if let Some(row) = sqlx::query(
        "select id, body, delivery_state, length(body) as body_len from messages where stream_key = $1",
    )
    .bind(stream_key)
    .fetch_optional(pool)
    .await
    .map_err(to_string)?
    {
        let message_id: Uuid = row.get("id");
        let body: String = row.get("body");
        let delivery_state: String = row.get("delivery_state");
        if delivery_state != "streaming" {
            return Ok(message_id);
        }
        let body_len: i32 = row.get("body_len");
        let (append_delta, truncated) = capped_stream_delta(delta, body_len.max(0) as usize);
        if append_delta.is_empty() && truncated {
            if complete_on_truncation {
                finish_streaming_agent_message(pool, stream_key, "complete").await?;
            }
            return Ok(message_id);
        }
        let delivery_state = if truncated && complete_on_truncation {
            "complete"
        } else {
            "streaming"
        };
        if let Some((control_agent_id, run_id, _)) =
            load_streaming_control_context(pool, stream_key).await?
        {
            let next_body = format!("{body}{append_delta}");
            let (visible_body, event_jsons) = split_complete_streaming_agent_event_lines(&next_body);
            if !event_jsons.is_empty() {
                for json in &event_jsons {
                    handle_streaming_agent_event_json(pool, control_agent_id, run_id, json).await?;
                }
                if visible_body.is_empty() {
                    sqlx::query("delete from messages where id = $1")
                        .bind(message_id)
                        .execute(pool)
                        .await
                        .map_err(to_string)?;
                    let _ = notify_ui_message_delete(pool, message_id, "stream_event_consumed")
                        .await;
                    return Ok(message_id);
                }
                sqlx::query(
                    "update messages set body = $2, delivery_state = $3, updated_at = strftime('%Y-%m-%dT%H:%M:%f+00:00','now') where id = $1",
                )
                .bind(message_id)
                .bind(&visible_body)
                .bind(delivery_state)
                .execute(pool)
                .await
                .map_err(to_string)?;
                if let Ok(message) = load_message(pool, message_id).await {
                    let _ = notify_ui_message_upsert(pool, &message, "stream_event_consumed").await;
                } else {
                    let _ = notify_ui_refresh(pool, "stream_event_consumed").await;
                }
                if truncated && complete_on_truncation {
                    bump_thread_version(pool, channel_id, thread_root_id).await?;
                    queue_agent_message_mentions(pool, message_id).await?;
                }
                return Ok(message_id);
            }
        }
        sqlx::query(
            "update messages set body = body || $2, delivery_state = $3, updated_at = strftime('%Y-%m-%dT%H:%M:%f+00:00','now') where id = $1",
        )
            .bind(message_id)
            .bind(&append_delta)
            .bind(delivery_state)
            .execute(pool)
            .await
            .map_err(to_string)?;
        let _ = notify_ui_message_delta(
            pool,
            message_id,
            &append_delta,
            delivery_state,
            "stream_delta",
        )
        .await;
        if let Some((control_agent_id, run_id, _)) =
            load_streaming_control_context(pool, stream_key).await?
        {
            let _ = consume_complete_streaming_agent_control_lines(
                pool,
                control_agent_id,
                run_id,
                stream_key,
            )
            .await;
        }
        if truncated && complete_on_truncation {
            bump_thread_version(pool, channel_id, thread_root_id).await?;
            queue_agent_message_mentions(pool, message_id).await?;
        }
        return Ok(message_id);
    }

    delete_superseded_empty_run_progress_messages(
        pool,
        agent_id,
        channel_id,
        thread_root_id,
        stream_key,
    )
    .await?;

    if let Some((control_agent_id, run_id, work_item_id)) =
        load_streaming_control_context(pool, stream_key).await?
    {
        let decision = can_publish_public_output(
            pool,
            control_agent_id,
            channel_id,
            thread_root_id,
            work_item_id,
            PublishActionKind::ReplyText,
        )
        .await?;
        if !matches!(decision, PublishDecision::Allow) {
            return hold_streaming_public_output(
                pool,
                control_agent_id,
                run_id,
                work_item_id,
                channel_id,
                thread_root_id,
                stream_key,
                delta,
                false,
                decision,
            )
            .await;
        }
    }

    let sender = sqlx::query("select display_name, role from agents where id = $1")
        .bind(agent_id)
        .fetch_one(pool)
        .await
        .map_err(to_string)?;
    let sender_name: String = sender.get("display_name");
    let sender_role: String = sender.get("role");
    let (initial_body, truncated) = capped_stream_delta(delta, 0);
    let delivery_state = if truncated && complete_on_truncation {
        "complete"
    } else {
        "streaming"
    };
    let mut insert_body = initial_body.clone();
    let mut event_jsons = Vec::new();
    let control_context = load_streaming_control_context(pool, stream_key).await?;
    if control_context.is_some() {
        let (visible_body, events) = split_complete_streaming_agent_event_lines(&initial_body);
        if !events.is_empty() {
            insert_body = visible_body;
            event_jsons = events;
        }
    }

    let message_id: Uuid = sqlx::query_scalar(
        r#"
        insert into messages (
            channel_id,
            thread_root_id,
            sender_agent_id,
            sender_name,
            sender_role,
            body,
            is_task,
            delivery_state,
            stream_key
        )
        values ($1, $2, $3, $4, $5, $6, false, $7, $8)
        returning id
        "#,
    )
    .bind(channel_id)
    .bind(thread_root_id)
    .bind(agent_id)
    .bind(sender_name)
    .bind(sender_role)
    .bind(&insert_body)
    .bind(delivery_state)
    .bind(stream_key)
    .fetch_one(pool)
    .await
    .map_err(to_string)?;

    if let Some((control_agent_id, run_id, _)) = control_context {
        for json in &event_jsons {
            handle_streaming_agent_event_json(pool, control_agent_id, run_id, json).await?;
        }
        if !event_jsons.is_empty() && insert_body.is_empty() {
            delete_streaming_agent_message(pool, message_id, "stream_event_consumed").await?;
            return Ok(message_id);
        }
    }

    if insert_body.is_empty() {
        let _ = notify_ui_refresh(pool, "stream_start").await;
    } else if let Ok(message) = load_message(pool, message_id).await {
        let _ = notify_ui_message_upsert(pool, &message, "stream_start").await;
    } else {
        let _ = notify_ui_refresh(pool, "stream_start").await;
    }
    if let Some((control_agent_id, run_id, _)) =
        load_streaming_control_context(pool, stream_key).await?
    {
        let _ = consume_complete_streaming_agent_control_lines(
            pool,
            control_agent_id,
            run_id,
            stream_key,
        )
        .await;
    }
    if truncated && complete_on_truncation {
        bump_thread_version(pool, channel_id, thread_root_id).await?;
        queue_agent_message_mentions(pool, message_id).await?;
    }
    Ok(message_id)
}

async fn ensure_streaming_agent_message(
    pool: &SqlitePool,
    agent_id: Uuid,
    channel_id: Uuid,
    thread_root_id: Option<Uuid>,
    stream_key: &str,
) -> CommandResult<Uuid> {
    if stream_key.trim().is_empty() {
        return Err("stream_key is empty".to_owned());
    }
    if output_buffer_exists(pool, stream_key).await? {
        return Ok(Uuid::new_v4());
    }

    if let Some(existing) = sqlx::query_scalar("select id from messages where stream_key = $1")
        .bind(stream_key)
        .fetch_optional(pool)
        .await
        .map_err(to_string)?
    {
        return Ok(existing);
    }

    if let Some((control_agent_id, run_id, work_item_id)) =
        load_streaming_control_context(pool, stream_key).await?
    {
        let decision = can_publish_public_output(
            pool,
            control_agent_id,
            channel_id,
            thread_root_id,
            work_item_id,
            PublishActionKind::ReplyText,
        )
        .await?;
        if !matches!(decision, PublishDecision::Allow) {
            return hold_streaming_public_output(
                pool,
                control_agent_id,
                run_id,
                work_item_id,
                channel_id,
                thread_root_id,
                stream_key,
                "",
                false,
                decision,
            )
            .await;
        }
    }

    let sender = sqlx::query("select display_name, role from agents where id = $1")
        .bind(agent_id)
        .fetch_one(pool)
        .await
        .map_err(to_string)?;
    let sender_name: String = sender.get("display_name");
    let sender_role: String = sender.get("role");
    let message_id: Uuid = sqlx::query_scalar(
        r#"
        insert into messages (
            channel_id,
            thread_root_id,
            sender_agent_id,
            sender_name,
            sender_role,
            body,
            is_task,
            delivery_state,
            stream_key
        )
        values ($1, $2, $3, $4, $5, '', false, 'streaming', $6)
        returning id
        "#,
    )
    .bind(channel_id)
    .bind(thread_root_id)
    .bind(agent_id)
    .bind(sender_name)
    .bind(sender_role)
    .bind(stream_key)
    .fetch_one(pool)
    .await
    .map_err(to_string)?;

    if let Ok(message) = load_message(pool, message_id).await {
        let _ = notify_ui_message_upsert(pool, &message, "stream_placeholder").await;
    } else {
        let _ = notify_ui_refresh(pool, "stream_placeholder").await;
    }
    Ok(message_id)
}

async fn adopt_streaming_agent_message_key(
    pool: &SqlitePool,
    pending_stream_key: &str,
    stream_key: &str,
) -> CommandResult<Option<Uuid>> {
    if pending_stream_key == stream_key {
        return Ok(None);
    }
    if streaming_message_exists(pool, stream_key).await? {
        return Ok(None);
    }

    let message_id: Option<Uuid> = sqlx::query_scalar(
        r#"
        update messages
        set stream_key = $2,
            updated_at = strftime('%Y-%m-%dT%H:%M:%f+00:00','now')
        where stream_key = $1
          and delivery_state = 'streaming'
          and body = ''
        returning id
        "#,
    )
    .bind(pending_stream_key)
    .bind(stream_key)
    .fetch_optional(pool)
    .await
    .map_err(to_string)?;

    if let Some(message_id) = message_id {
        if let Ok(message) = load_message(pool, message_id).await {
            let _ = notify_ui_message_upsert(pool, &message, "stream_key_adopted").await;
        } else {
            let _ = notify_ui_refresh(pool, "stream_key_adopted").await;
        }
    }
    Ok(message_id)
}

async fn streaming_message_body_is_empty(
    pool: &SqlitePool,
    stream_key: &str,
) -> CommandResult<bool> {
    let body: Option<String> =
        sqlx::query_scalar("select body from messages where stream_key = $1")
            .bind(stream_key)
            .fetch_optional(pool)
            .await
            .map_err(to_string)?;
    Ok(body.map(|body| body.is_empty()).unwrap_or(true))
}

async fn delete_streaming_agent_message(
    pool: &SqlitePool,
    message_id: Uuid,
    reason: &str,
) -> CommandResult<()> {
    sqlx::query("delete from messages where id = $1")
        .bind(message_id)
        .execute(pool)
        .await
        .map_err(to_string)?;
    let _ = notify_ui_message_delete(pool, message_id, reason).await;
    Ok(())
}

async fn delete_superseded_empty_run_progress_messages(
    pool: &SqlitePool,
    agent_id: Uuid,
    channel_id: Uuid,
    thread_root_id: Option<Uuid>,
    stream_key: &str,
) -> CommandResult<()> {
    let Some(run_prefix) = stream_key
        .split(':')
        .next()
        .filter(|value| !value.is_empty())
    else {
        return Ok(());
    };
    if Uuid::parse_str(run_prefix).is_err() {
        return Ok(());
    }

    let superseded_ids: Vec<Uuid> = sqlx::query_scalar(
        r#"
        select id
        from messages
        where sender_agent_id = $1
          and channel_id = $2
          and thread_root_id is not distinct from $3
          and stream_key <> $4
          and stream_key like $5
          and body = ''
          and delivery_state in ('streaming', 'complete')
        "#,
    )
    .bind(agent_id)
    .bind(channel_id)
    .bind(thread_root_id)
    .bind(stream_key)
    .bind(format!("{run_prefix}:%"))
    .fetch_all(pool)
    .await
    .map_err(to_string)?;

    for message_id in superseded_ids {
        delete_streaming_agent_message(pool, message_id, "superseded_progress_status").await?;
    }
    Ok(())
}

async fn delete_intermediate_run_messages(
    pool: &SqlitePool,
    agent_id: Uuid,
    channel_id: Uuid,
    thread_root_id: Option<Uuid>,
    run_id: Uuid,
) -> CommandResult<()> {
    let superseded_ids: Vec<Uuid> = sqlx::query_scalar(
        r#"
        select id
        from messages
        where sender_agent_id = $1
          and channel_id = $2
          and thread_root_id is not distinct from $3
          and stream_key like $4
          and body <> ''
          and delivery_state in ('streaming', 'complete')
        "#,
    )
    .bind(agent_id)
    .bind(channel_id)
    .bind(thread_root_id)
    .bind(format!("{run_id}:%"))
    .fetch_all(pool)
    .await
    .map_err(to_string)?;

    for message_id in superseded_ids {
        delete_streaming_agent_message(pool, message_id, "superseded_intermediate_reply").await?;
    }
    Ok(())
}

async fn finish_streaming_agent_message(
    pool: &SqlitePool,
    stream_key: &str,
    delivery_state: &str,
) -> CommandResult<()> {
    finish_streaming_agent_message_inner(pool, stream_key, delivery_state, true).await
}

async fn finish_streaming_agent_message_deferred_mentions(
    pool: &SqlitePool,
    stream_key: &str,
    delivery_state: &str,
) -> CommandResult<()> {
    finish_streaming_agent_message_inner(pool, stream_key, delivery_state, false).await
}

async fn finish_streaming_agent_message_inner(
    pool: &SqlitePool,
    stream_key: &str,
    delivery_state: &str,
    dispatch_mentions: bool,
) -> CommandResult<()> {
    if output_buffer_exists(pool, stream_key).await? {
        if let Some((agent_id, run_id, work_item_id)) =
            load_streaming_control_context(pool, stream_key).await?
        {
            let row = sqlx::query(
                "select channel_id, thread_root_id from agent_output_buffers where stream_key = $1",
            )
            .bind(stream_key)
            .fetch_optional(pool)
            .await
            .map_err(to_string)?;
            if let Some(row) = row {
                let channel_id: Uuid = row.get("channel_id");
                let thread_root_id: Option<Uuid> = row.get("thread_root_id");
                let _ = hold_streaming_public_output(
                    pool,
                    agent_id,
                    run_id,
                    work_item_id,
                    channel_id,
                    thread_root_id,
                    stream_key,
                    "",
                    true,
                    PublishDecision::HoldStale {
                        base_version: 0,
                        current_version: 0,
                    },
                )
                .await?;
            }
        }
        return Ok(());
    }
    if delivery_state != "streaming" {
        if let Some((agent_id, run_id, work_item_id)) =
            load_streaming_control_context(pool, stream_key).await?
        {
            if consume_streaming_agent_control_lines(
                pool,
                agent_id,
                run_id,
                work_item_id,
                stream_key,
            )
            .await?
            {
                return Ok(());
            }
        }
    }

    if delivery_state == "complete" {
        let empty_message_id: Option<Uuid> = sqlx::query_scalar(
            r#"
            select id
            from messages
            where stream_key = $1
              and delivery_state = 'streaming'
              and trim(body) = ''
            "#,
        )
        .bind(stream_key)
        .fetch_optional(pool)
        .await
        .map_err(to_string)?;
        if let Some(message_id) = empty_message_id {
            delete_streaming_agent_message(pool, message_id, "empty_stream_complete").await?;
            return Ok(());
        }
    }

    let affected = sqlx::query(
        r#"
        update messages
        set delivery_state = $2
        where stream_key = $1
          and delivery_state = 'streaming'
        "#,
    )
    .bind(stream_key)
    .bind(delivery_state)
    .execute(pool)
    .await
    .map_err(to_string)?
    .rows_affected();
    if affected > 0 {
        let message_id: Option<Uuid> =
            sqlx::query_scalar("select id from messages where stream_key = $1")
                .bind(stream_key)
                .fetch_optional(pool)
                .await
                .map_err(to_string)?;
        if let Some(message_id) = message_id {
            if let Ok(message) = load_message(pool, message_id).await {
                if delivery_state == "complete" {
                    bump_thread_version(pool, message.channel_id, message.thread_root_id).await?;
                    if let Some((_, run_id, _)) =
                        load_streaming_control_context(pool, stream_key).await?
                    {
                        repin_run_work_item_to_current_surface(pool, run_id).await?;
                    }
                }
                let _ = notify_ui_message_upsert(pool, &message, "stream_finish").await;
            } else {
                let _ = notify_ui_refresh(pool, "stream_finish").await;
            }
            if delivery_state == "complete" && dispatch_mentions {
                queue_agent_message_mentions(pool, message_id).await?;
            }
        }
    }
    Ok(())
}

async fn dispatch_streaming_agent_message_mentions(
    pool: &SqlitePool,
    stream_key: &str,
) -> CommandResult<()> {
    let message_id: Option<Uuid> = sqlx::query_scalar(
        "select id from messages where stream_key = $1 and delivery_state = 'complete'",
    )
    .bind(stream_key)
    .fetch_optional(pool)
    .await
    .map_err(to_string)?;
    if let Some(message_id) = message_id {
        queue_agent_message_mentions(pool, message_id).await?;
    }
    Ok(())
}

async fn load_streaming_control_context(
    pool: &SqlitePool,
    stream_key: &str,
) -> CommandResult<Option<(Uuid, Uuid, Option<Uuid>)>> {
    let Some(run_prefix) = stream_key
        .split(':')
        .next()
        .filter(|value| !value.is_empty())
    else {
        return Ok(None);
    };
    let Ok(run_id) = Uuid::parse_str(run_prefix) else {
        return Ok(None);
    };
    let Some(row) = sqlx::query("select agent_id, work_item_id from agent_runs where id = $1")
        .bind(run_id)
        .fetch_optional(pool)
        .await
        .map_err(to_string)?
    else {
        return Ok(None);
    };
    let agent_id: Uuid = row.get("agent_id");
    let work_item_id: Option<Uuid> = row.get("work_item_id");
    Ok(Some((agent_id, run_id, work_item_id)))
}

fn silent_reply_reason(body: &str) -> Option<String> {
    let first_line = body.trim().lines().next()?.trim().trim_matches('`').trim();
    let rest = first_line.strip_prefix(SILENT_REPLY_PREFIX)?;
    if !rest.is_empty()
        && !rest.starts_with(':')
        && !rest
            .chars()
            .next()
            .map(char::is_whitespace)
            .unwrap_or(false)
    {
        return None;
    }
    let reason = rest.trim_start_matches(':').trim();
    Some(reason.to_owned())
}

async fn mark_work_item_silent(
    pool: &SqlitePool,
    agent_id: Uuid,
    run_id: Uuid,
    work_item_id: Uuid,
    reason: &str,
) -> CommandResult<()> {
    sqlx::query(
        r#"
        update agent_work_items
        set status = 'silent',
            completed_at = coalesce(completed_at, strftime('%Y-%m-%dT%H:%M:%f+00:00','now')),
            updated_at = strftime('%Y-%m-%dT%H:%M:%f+00:00','now')
        where id = $1
          and status not in ('cancelled', 'failed')
        "#,
    )
    .bind(work_item_id)
    .execute(pool)
    .await
    .map_err(to_string)?;
    notify_ui_work_item_changed(pool, work_item_id, "work_item_silent").await;
    record_agent_activity(
        pool,
        Some(agent_id),
        Some(run_id),
        "decision",
        "No visible reply needed",
        json!({
            "work_item_id": work_item_id,
            "reason": if reason.trim().is_empty() {
                "Agent judged the message as non-actionable."
            } else {
                reason.trim()
            }
        })
        .to_string(),
    )
    .await?;
    Ok(())
}

async fn mark_run_work_item_silent(
    pool: &SqlitePool,
    agent_id: Uuid,
    run_id: Uuid,
    reason: &str,
) -> CommandResult<()> {
    let work_item_id: Option<Uuid> =
        sqlx::query_scalar("select work_item_id from agent_runs where id = $1 and agent_id = $2")
            .bind(run_id)
            .bind(agent_id)
            .fetch_optional(pool)
            .await
            .map_err(to_string)?
            .flatten();
    if let Some(work_item_id) = work_item_id {
        mark_work_item_silent(pool, agent_id, run_id, work_item_id, reason).await?;
    } else {
        record_agent_activity(
            pool,
            Some(agent_id),
            Some(run_id),
            "decision",
            "No visible reply needed",
            reason.trim(),
        )
        .await?;
    }
    Ok(())
}

async fn maybe_hide_silent_streaming_reply(
    pool: &SqlitePool,
    agent_id: Uuid,
    run_id: Uuid,
    work_item_id: Option<Uuid>,
    stream_key: &str,
) -> CommandResult<bool> {
    let Some(row) = sqlx::query("select id, body from messages where stream_key = $1")
        .bind(stream_key)
        .fetch_optional(pool)
        .await
        .map_err(to_string)?
    else {
        return Ok(false);
    };
    let message_id: Uuid = row.get("id");
    let body: String = row.get("body");
    let Some(reason) = silent_reply_reason(&body) else {
        return Ok(false);
    };

    delete_streaming_agent_message(pool, message_id, "silent_reply").await?;
    if let Some(work_item_id) = work_item_id {
        mark_work_item_silent(pool, agent_id, run_id, work_item_id, &reason).await?;
    } else {
        record_agent_activity(
            pool,
            Some(agent_id),
            Some(run_id),
            "decision",
            "No visible reply needed",
            reason.trim(),
        )
        .await?;
    }
    Ok(true)
}

fn split_streaming_agent_event_lines(body: &str) -> (String, Vec<String>) {
    split_agent_event_jsons_from_text(body, false)
}

fn split_complete_streaming_agent_event_lines(body: &str) -> (String, Vec<String>) {
    split_streaming_agent_event_lines(body)
}

fn split_terminal_streaming_agent_event_lines(body: &str) -> (String, Vec<String>) {
    split_agent_event_jsons_from_text(body, true)
}

fn streaming_agent_event_is_visible_side_effect(json: &str) -> bool {
    let Ok(value) = serde_json::from_str::<Value>(json) else {
        return false;
    };
    match value.get("type").and_then(Value::as_str) {
        Some(
            "message"
            | "channel_message_create"
            | "task_create"
            | "attachment_create"
            | "handoff_create",
        ) => true,
        Some("artifact_create") => {
            let kind_supported = value
                .get("kind")
                .and_then(Value::as_str)
                .is_some_and(|kind| normalize_artifact_kind(kind).is_ok());
            let has_title = value
                .get("title")
                .and_then(Value::as_str)
                .is_some_and(|title| !title.trim().is_empty());
            let has_content = value
                .get("content")
                .and_then(Value::as_str)
                .is_some_and(|content| !content.trim().is_empty());
            kind_supported && has_title && has_content
        }
        _ => false,
    }
}

async fn handle_streaming_agent_event_json(
    pool: &SqlitePool,
    agent_id: Uuid,
    run_id: Uuid,
    json: &str,
) -> CommandResult<()> {
    match serde_json::from_str::<AgentEvent>(json).map_err(to_string) {
        Ok(event) => {
            if !claim_agent_event(pool, run_id, json).await? {
                return Ok(());
            }
            if let Some(note) =
                maybe_hold_visible_streaming_event(pool, agent_id, run_id, json, &event).await?
            {
                append_run_log(pool, run_id, format!("[stream-event] {note}\n")).await?;
                record_agent_activity(
                    pool,
                    Some(agent_id),
                    Some(run_id),
                    "event",
                    "Stream event held",
                    note,
                )
                .await?;
                return Ok(());
            }
            match handle_agent_event(pool, agent_id, run_id, event).await {
                Ok(note) => {
                    repin_run_work_item_to_current_surface(pool, run_id).await?;
                    append_run_log(pool, run_id, format!("[stream-event] {note}\n")).await?;
                    record_agent_activity(
                        pool,
                        Some(agent_id),
                        Some(run_id),
                        "event",
                        "Stream event accepted",
                        note,
                    )
                    .await?;
                }
                Err(err) => {
                    append_run_log(pool, run_id, format!("[stream-event] rejected: {err}\n"))
                        .await?;
                    record_agent_activity(
                        pool,
                        Some(agent_id),
                        Some(run_id),
                        "event_error",
                        "Stream event rejected",
                        err,
                    )
                    .await?;
                }
            }
        }
        Err(err) => {
            append_run_log(pool, run_id, format!("[stream-event] rejected: {err}\n")).await?;
            record_agent_activity(
                pool,
                Some(agent_id),
                Some(run_id),
                "event_error",
                "Stream event rejected",
                err,
            )
            .await?;
        }
    }
    Ok(())
}

async fn handle_claimed_agent_event_json(
    pool: &SqlitePool,
    agent_id: Uuid,
    run_id: Uuid,
    json: &str,
) -> CommandResult<String> {
    let event: AgentEvent = serde_json::from_str(json).map_err(to_string)?;
    Box::pin(handle_agent_event(pool, agent_id, run_id, event)).await
}

async fn maybe_hold_visible_streaming_event(
    pool: &SqlitePool,
    agent_id: Uuid,
    run_id: Uuid,
    json: &str,
    event: &AgentEvent,
) -> CommandResult<Option<String>> {
    let (channel_id, thread_root_id, action_kind) = match event {
        AgentEvent::Message {
            channel,
            channel_id,
            thread_root_id,
            ..
        } => (
            resolve_event_channel(pool, *channel_id, channel.as_deref()).await?,
            *thread_root_id,
            control_action_kind_for_event_type("message"),
        ),
        AgentEvent::ChannelMessageCreate {
            channel,
            channel_id,
            thread_root_id,
            ..
        } => (
            resolve_event_channel(pool, *channel_id, channel.as_deref()).await?,
            *thread_root_id,
            control_action_kind_for_event_type("channel_message_create"),
        ),
        AgentEvent::ArtifactCreate {
            channel,
            channel_id,
            thread_root_id,
            ..
        } => (
            resolve_event_channel(pool, *channel_id, channel.as_deref()).await?,
            *thread_root_id,
            control_action_kind_for_event_type("artifact_create"),
        ),
        AgentEvent::AttachmentCreate {
            channel,
            channel_id,
            thread_root_id,
            ..
        } => (
            resolve_event_channel(pool, *channel_id, channel.as_deref()).await?,
            *thread_root_id,
            control_action_kind_for_event_type("attachment_create"),
        ),
        AgentEvent::HandoffCreate {
            channel,
            channel_id,
            thread_root_id,
            ..
        } => (
            resolve_event_channel(pool, *channel_id, channel.as_deref()).await?,
            Some(*thread_root_id),
            control_action_kind_for_event_type("handoff_create"),
        ),
        AgentEvent::TaskCreate {
            channel,
            channel_id,
            ..
        } => (
            resolve_event_channel(pool, *channel_id, channel.as_deref()).await?,
            None,
            control_action_kind_for_event_type("task_create"),
        ),
        _ => return Ok(None),
    };
    let work_item_id = run_work_item_id(pool, run_id).await?;
    let (gate_channel_id, gate_thread_root_id) = work_item_public_surface(pool, work_item_id)
        .await?
        .unwrap_or((channel_id, thread_root_id));
    let decision = can_publish_public_output(
        pool,
        agent_id,
        gate_channel_id,
        gate_thread_root_id,
        work_item_id,
        action_kind,
    )
    .await?;
    if matches!(decision, PublishDecision::Allow) {
        return Ok(None);
    }
    hold_visible_control_event(
        pool,
        agent_id,
        run_id,
        work_item_id,
        gate_channel_id,
        gate_thread_root_id,
        action_kind,
        json,
        decision,
    )
    .await
    .map(Some)
}

async fn consume_complete_streaming_agent_control_lines(
    pool: &SqlitePool,
    agent_id: Uuid,
    run_id: Uuid,
    stream_key: &str,
) -> CommandResult<bool> {
    let Some(row) = sqlx::query("select id, body from messages where stream_key = $1")
        .bind(stream_key)
        .fetch_optional(pool)
        .await
        .map_err(to_string)?
    else {
        return Ok(false);
    };
    let message_id: Uuid = row.get("id");
    let body: String = row.get("body");
    let (visible_body, event_jsons) = split_complete_streaming_agent_event_lines(&body);
    if event_jsons.is_empty() {
        return Ok(false);
    }

    for json in &event_jsons {
        handle_streaming_agent_event_json(pool, agent_id, run_id, json).await?;
    }

    if visible_body.is_empty() {
        delete_streaming_agent_message(pool, message_id, "stream_event_consumed").await?;
        return Ok(true);
    }

    sqlx::query("update messages set body = $2, updated_at = strftime('%Y-%m-%dT%H:%M:%f+00:00','now') where id = $1")
        .bind(message_id)
        .bind(&visible_body)
        .execute(pool)
        .await
        .map_err(to_string)?;
    if let Ok(message) = load_message(pool, message_id).await {
        let _ = notify_ui_message_upsert(pool, &message, "stream_event_consumed").await;
    } else {
        let _ = notify_ui_refresh(pool, "stream_event_consumed").await;
    }
    Ok(true)
}

async fn consume_streaming_agent_control_lines(
    pool: &SqlitePool,
    agent_id: Uuid,
    run_id: Uuid,
    work_item_id: Option<Uuid>,
    stream_key: &str,
) -> CommandResult<bool> {
    if maybe_hide_silent_streaming_reply(pool, agent_id, run_id, work_item_id, stream_key).await? {
        return Ok(true);
    }

    let Some(row) = sqlx::query("select id, body from messages where stream_key = $1")
        .bind(stream_key)
        .fetch_optional(pool)
        .await
        .map_err(to_string)?
    else {
        return Ok(false);
    };
    let message_id: Uuid = row.get("id");
    let body: String = row.get("body");
    let (visible_body, event_jsons) = split_terminal_streaming_agent_event_lines(&body);
    let body_changed = visible_body != body;
    if event_jsons.is_empty() && !body_changed {
        return Ok(false);
    }

    for json in &event_jsons {
        handle_streaming_agent_event_json(pool, agent_id, run_id, json).await?;
    }

    if visible_body.is_empty() {
        delete_streaming_agent_message(pool, message_id, "stream_event_consumed").await?;
        return Ok(true);
    }

    sqlx::query("update messages set body = $2 where id = $1")
        .bind(message_id)
        .bind(&visible_body)
        .execute(pool)
        .await
        .map_err(to_string)?;
    if let Ok(message) = load_message(pool, message_id).await {
        let _ = notify_ui_message_upsert(pool, &message, "stream_event_consumed").await;
    } else {
        let _ = notify_ui_refresh(pool, "stream_event_consumed").await;
    }
    Ok(false)
}

async fn load_runtime_thread_id(
    pool: &SqlitePool,
    agent_id: Uuid,
    runtime: &str,
) -> CommandResult<Option<String>> {
    let thread_id: Option<String> = sqlx::query_scalar(
        r#"
        select provider_thread_id
        from runtime_sessions
        where agent_id = $1
          and runtime = $2
        "#,
    )
    .bind(agent_id)
    .bind(runtime)
    .fetch_optional(pool)
    .await
    .map_err(to_string)?;
    Ok(thread_id.filter(|thread_id| !thread_id.trim().is_empty()))
}

async fn upsert_runtime_thread_id(
    pool: &SqlitePool,
    agent_id: Uuid,
    runtime: &str,
    provider_thread_id: &str,
    status: &str,
) -> CommandResult<()> {
    sqlx::query(
        r#"
        insert into runtime_sessions (agent_id, runtime, provider_thread_id, status)
        values ($1, $2, $3, $4)
        on conflict (agent_id, runtime) do update set
            provider_thread_id = excluded.provider_thread_id,
            status = excluded.status,
            updated_at = strftime('%Y-%m-%dT%H:%M:%f+00:00','now')
        "#,
    )
    .bind(agent_id)
    .bind(runtime)
    .bind(provider_thread_id)
    .bind(status)
    .execute(pool)
    .await
    .map_err(to_string)?;
    Ok(())
}

async fn wait_for_agent_run(
    pool: SqlitePool,
    agent_id: Uuid,
    run_id: Uuid,
    work_item_id: Option<Uuid>,
    pipe_tasks: Vec<tokio::task::JoinHandle<()>>,
    mut child: tokio::process::Child,
) {
    let result = child.wait().await;
    for task in pipe_tasks {
        let _ = task.await;
    }
    let _ = replay_agent_events_from_run_log_if_needed(&pool, agent_id, run_id).await;
    let current_run_status: Option<String> =
        sqlx::query_scalar("select status from agent_runs where id = $1")
            .bind(run_id)
            .fetch_optional(&pool)
            .await
            .ok()
            .flatten();
    let (run_status, agent_status, exit_code, log_line) = match result {
        _ if current_run_status.as_deref() == Some("failed") => (
            "failed",
            "error",
            None,
            "process exited after runtime error\n".to_owned(),
        ),
        Ok(status) if status.success() => (
            "exited",
            "idle",
            status.code(),
            format!("process exited successfully: {status}\n"),
        ),
        Ok(status) => (
            "stopped",
            "idle",
            status.code(),
            format!("process stopped: {status}\n"),
        ),
        Err(err) => (
            "failed",
            "error",
            None,
            format!("failed while waiting for process: {err}\n"),
        ),
    };

    let _ = sqlx::query(
        r#"
        update agent_runs
        set status = $2,
            exit_code = $3,
            log = substr(log || $4, -20000),
            stopped_at = strftime('%Y-%m-%dT%H:%M:%f+00:00','now')
        where id = $1
        "#,
    )
    .bind(run_id)
    .bind(run_status)
    .bind(exit_code)
    .bind(&log_line)
    .execute(&pool)
    .await;
    notify_ui_agent_run_changed(&pool, run_id, "run_finished").await;

    let _ = sqlx::query("update agents set status = $2 where id = $1")
        .bind(agent_id)
        .bind(agent_status)
        .execute(&pool)
        .await;
    notify_ui_agent_changed(&pool, agent_id, "agent_finished").await;

    if let Some(work_item_id) = work_item_id {
        let current_status: Option<String> =
            sqlx::query_scalar("select status from agent_work_items where id = $1")
                .bind(work_item_id)
                .fetch_optional(&pool)
                .await
                .ok()
                .flatten();
        let work_status = if current_status.as_deref() == Some("cancelling") {
            "cancelled"
        } else if current_status.as_deref() == Some("silent") && run_status == "exited" {
            "silent"
        } else if run_status == "exited"
            && run_has_visible_message_result(&pool, run_id)
                .await
                .unwrap_or(false)
        {
            "done"
        } else {
            "failed"
        };
        let _ = sqlx::query(
            r#"
            update agent_work_items
            set status = $2,
                completed_at = strftime('%Y-%m-%dT%H:%M:%f+00:00','now'),
                updated_at = strftime('%Y-%m-%dT%H:%M:%f+00:00','now')
            where id = $1
            "#,
        )
        .bind(work_item_id)
        .bind(work_status)
        .execute(&pool)
        .await;
        let _ =
            mark_task_after_work_item_finished(&pool, work_item_id, agent_id, run_id, work_status)
                .await;
        notify_ui_work_item_changed(&pool, work_item_id, "work_item_finished").await;
        let _ = record_agent_activity(
            &pool,
            Some(agent_id),
            Some(run_id),
            "dispatch",
            work_status_title(work_status),
            work_item_id.to_string(),
        )
        .await;
    }

    let _ = record_agent_activity(
        &pool,
        Some(agent_id),
        Some(run_id),
        "run",
        format!("Run {run_status}"),
        log_line.trim(),
    )
    .await;
}

async fn run_has_visible_message_result(pool: &SqlitePool, run_id: Uuid) -> CommandResult<bool> {
    let stream_prefix = format!("{run_id}:%");
    let count: i64 = sqlx::query_scalar(
        r#"
        select count(*)
        from messages
        where trim(body) <> ''
          and stream_key like $1
        "#,
    )
    .bind(stream_prefix)
    .fetch_one(pool)
    .await
    .map_err(to_string)?;
    Ok(count > 0)
}

fn effective_launch_command(
    launch_command: String,
    _runtime: String,
    _model: String,
    _handle: String,
) -> String {
    if !launch_command.trim().is_empty() {
        return launch_command.trim().to_owned();
    }

    "printf 'Lantor placeholder runtime. Configure launch_command to run a real agent.\\n'; sleep 3600"
        .to_owned()
}

async fn load_channel_agent_roster(
    pool: &SqlitePool,
    channel_id: Option<Uuid>,
    current_agent_id: Uuid,
) -> CommandResult<Vec<String>> {
    let Some(channel_id) = channel_id else {
        return Ok(vec![]);
    };
    let rows = sqlx::query(
        r#"
        select a.handle, a.display_name, a.runtime, a.model, a.status
        from channels c
        join channel_members cm on cm.channel_id = c.id
        join agents a on a.id = cm.agent_id
        where c.id = $1
          and c.kind = 'channel'
          and a.id <> $2
        order by lower(a.handle)
        "#,
    )
    .bind(channel_id)
    .bind(current_agent_id)
    .fetch_all(pool)
    .await
    .map_err(to_string)?;

    Ok(rows
        .into_iter()
        .map(|row| {
            let handle: String = row.get("handle");
            let display_name: String = row.get("display_name");
            let runtime: String = row.get("runtime");
            let model: String = row.get("model");
            let status: String = row.get("status");
            format!("@{handle} - {display_name} - {runtime}/{model} - {status}")
        })
        .collect())
}

