async fn wait_for_warm_codex_process(
    pool: SqlitePool,
    registry: WarmCodexRegistry,
    agent_id: Uuid,
    runtime: Arc<WarmCodexRuntime>,
    mut child: tokio::process::Child,
) {
    let wait_result = child.wait().await;
    {
        let mut state = runtime.state.lock().await;
        state.alive = false;
    }
    let detail = match wait_result {
        Ok(status) => format!("codex app-server exited: {status}"),
        Err(err) => format!("codex app-server wait failed: {err}"),
    };
    let _ =
        finish_warm_codex_active_turn(&pool, agent_id, &runtime, false, Some(detail.clone())).await;
    let _ = sqlx::query(
        r#"
        update runtime_sessions
        set status = 'stopped', updated_at = strftime('%Y-%m-%dT%H:%M:%f+00:00','now')
        where agent_id = $1
          and runtime = 'codex'
          and provider_thread_id = $2
        "#,
    )
    .bind(agent_id)
    .bind(&runtime.thread_id)
    .execute(&pool)
    .await;
    let _ = record_agent_activity(
        &pool,
        Some(agent_id),
        None,
        "run",
        "Codex warm app-server exited",
        detail,
    )
    .await;
    remove_warm_codex_runtime_if_same(&registry, agent_id, &runtime).await;
    let _ = notify_supervisor_wake(&pool).await;
}

async fn remove_warm_codex_runtime_if_same(
    registry: &WarmCodexRegistry,
    agent_id: Uuid,
    runtime: &Arc<WarmCodexRuntime>,
) {
    let mut runtimes = registry.runtimes.lock().await;
    if runtimes
        .get(&agent_id)
        .map(|current| Arc::ptr_eq(current, runtime))
        .unwrap_or(false)
    {
        runtimes.remove(&agent_id);
    }
}

async fn terminate_process_group(pid: i32) -> CommandResult<()> {
    let status = Command::new("kill")
        .arg("-TERM")
        .arg(format!("-{pid}"))
        .status()
        .await
        .map_err(to_string)?;

    if !status.success() {
        return Err(format!("failed to terminate process group {pid}: {status}"));
    }

    Ok(())
}

async fn reap_stuck_codex_runtime(
    pool: &SqlitePool,
    registry: &WarmCodexRegistry,
    agent_id: Uuid,
    runtime: &Arc<WarmCodexRuntime>,
    source: &str,
) -> CommandResult<bool> {
    let (pid, elapsed_ms, reason) = {
        let mut state = runtime.state.lock().await;
        let Some(active) = state.active.as_ref() else {
            return Ok(false);
        };
        let elapsed = active.started_at.elapsed();
        let Some(reason) = codex_active_turn_reap_reason(
            active.turn_id.as_deref(),
            active.first_model_activity_at.is_some(),
            elapsed,
            state.last_activity.elapsed(),
        ) else {
            return Ok(false);
        };
        let elapsed_ms = elapsed.as_millis();
        state.alive = false;
        (runtime.pid, elapsed_ms, reason)
    };

    let detail_reason = match reason {
        CodexActiveTurnReapReason::StuckBeforeTurnId => "no turn id",
    };
    let detail = format!(
        "{detail_reason} after {elapsed_ms} ms; source={source}; process_group={}",
        pid.map(|pid| pid.to_string())
            .unwrap_or_else(|| "unavailable".to_owned())
    );
    finish_warm_codex_active_turn(pool, agent_id, runtime, false, Some(detail.clone())).await?;
    if let Some(pid) = pid {
        if let Err(err) = terminate_process_group(pid).await {
            record_agent_activity(
                pool,
                Some(agent_id),
                None,
                "run_error",
                "Codex zombie turn stop failed",
                err,
            )
            .await?;
        }
    }
    let _ = sqlx::query(
        "update runtime_sessions set status = 'failed', updated_at = strftime('%Y-%m-%dT%H:%M:%f+00:00','now') where agent_id = $1 and runtime = 'codex'",
    )
    .bind(agent_id)
    .execute(pool)
    .await;
    remove_warm_codex_runtime_if_same(registry, agent_id, runtime).await;
    record_agent_activity(
        pool,
        Some(agent_id),
        None,
        "run_error",
        "Codex zombie turn recovered",
        detail,
    )
    .await?;
    let _ = notify_supervisor_wake(pool).await;
    Ok(true)
}

async fn reap_stuck_codex_turn(
    pool: &SqlitePool,
    registry: &WarmCodexRegistry,
    agent_id: Uuid,
    source: &str,
) -> CommandResult<bool> {
    let runtime = {
        let runtimes = registry.runtimes.lock().await;
        runtimes.get(&agent_id).cloned()
    };
    let Some(runtime) = runtime else {
        return Ok(false);
    };
    reap_stuck_codex_runtime(pool, registry, agent_id, &runtime, source).await
}

async fn codex_warm_idle_reaper(
    pool: SqlitePool,
    registry: WarmCodexRegistry,
    agent_id: Uuid,
    runtime: Arc<WarmCodexRuntime>,
) {
    loop {
        sleep(CODEX_IDLE_REAPER_INTERVAL).await;
        let stop_reason = {
            let mut state = runtime.state.lock().await;
            if !state.alive {
                return;
            }
            if let Some(active) = state.active.as_ref() {
                codex_active_turn_reap_reason(
                    active.turn_id.as_deref(),
                    active.first_model_activity_at.is_some(),
                    active.started_at.elapsed(),
                    state.last_activity.elapsed(),
                )
                .map(|_| "zombie")
            } else if state.last_activity.elapsed() >= CODEX_IDLE_TIMEOUT {
                state.alive = false;
                Some("idle")
            } else {
                None
            }
        };
        let Some(stop_reason) = stop_reason else {
            continue;
        };
        if stop_reason == "zombie" {
            let _ =
                reap_stuck_codex_runtime(&pool, &registry, agent_id, &runtime, "idle_reaper").await;
            return;
        }

        let Some(pid) = runtime.pid else {
            return;
        };
        match terminate_process_group(pid).await {
            Ok(()) => {
                let _ = sqlx::query(
                    "update runtime_sessions set status = 'stopping', updated_at = strftime('%Y-%m-%dT%H:%M:%f+00:00','now') where agent_id = $1 and runtime = 'codex'",
                )
                .bind(agent_id)
                .execute(&pool)
                .await;
                let _ = record_agent_activity(
                    &pool,
                    Some(agent_id),
                    None,
                    "run",
                    "Codex warm app-server idle timeout",
                    format!("sent SIGTERM to process_group={pid}"),
                )
                .await;
            }
            Err(err) => {
                {
                    let mut state = runtime.state.lock().await;
                    state.alive = true;
                    state.last_activity = Instant::now();
                }
                let _ = record_agent_activity(
                    &pool,
                    Some(agent_id),
                    None,
                    "run_error",
                    "Codex warm app-server idle stop failed",
                    err,
                )
                .await;
            }
        }
        return;
    }
}

async fn wait_for_warm_claude_process(
    pool: SqlitePool,
    registry: WarmClaudeRegistry,
    agent_id: Uuid,
    runtime: Arc<WarmClaudeRuntime>,
    mut child: tokio::process::Child,
) {
    let wait_result = child.wait().await;
    {
        let mut state = runtime.state.lock().await;
        state.alive = false;
    }
    let detail = match wait_result {
        Ok(status) => format!("claude stream-json exited: {status}"),
        Err(err) => format!("claude stream-json wait failed: {err}"),
    };
    let _ = finish_warm_claude_active_turn(&pool, agent_id, &runtime, false, Some(detail.clone()))
        .await;
    let _ = sqlx::query(
        "update runtime_sessions set status = 'stopped', updated_at = strftime('%Y-%m-%dT%H:%M:%f+00:00','now') where agent_id = $1 and runtime = 'claude'",
    )
    .bind(agent_id)
    .execute(&pool)
    .await;
    let _ = record_agent_activity(
        &pool,
        Some(agent_id),
        None,
        "run",
        "Claude warm stream-json exited",
        detail,
    )
    .await;
    remove_warm_claude_runtime_if_same(&registry, agent_id, &runtime).await;
    let _ = notify_supervisor_wake(&pool).await;
}

async fn remove_warm_claude_runtime_if_same(
    registry: &WarmClaudeRegistry,
    agent_id: Uuid,
    runtime: &Arc<WarmClaudeRuntime>,
) {
    let mut runtimes = registry.runtimes.lock().await;
    if runtimes
        .get(&agent_id)
        .map(|current| Arc::ptr_eq(current, runtime))
        .unwrap_or(false)
    {
        runtimes.remove(&agent_id);
    }
}

async fn claude_warm_idle_reaper(
    pool: SqlitePool,
    agent_id: Uuid,
    runtime: Arc<WarmClaudeRuntime>,
) {
    loop {
        sleep(CODEX_IDLE_REAPER_INTERVAL).await;
        let should_stop = {
            let mut state = runtime.state.lock().await;
            let should_stop = state.alive
                && state.active.is_none()
                && state.last_activity.elapsed() >= CODEX_IDLE_TIMEOUT;
            if should_stop {
                state.alive = false;
            }
            should_stop
        };
        if !should_stop {
            if !runtime.state.lock().await.alive {
                return;
            }
            continue;
        }

        let Some(pid) = runtime.pid else {
            return;
        };
        match terminate_process_group(pid).await {
            Ok(()) => {
                let _ = sqlx::query(
                    "update runtime_sessions set status = 'stopping', updated_at = strftime('%Y-%m-%dT%H:%M:%f+00:00','now') where agent_id = $1 and runtime = 'claude'",
                )
                .bind(agent_id)
                .execute(&pool)
                .await;
                let _ = record_agent_activity(
                    &pool,
                    Some(agent_id),
                    None,
                    "run",
                    "Claude warm stream-json idle timeout",
                    format!("sent SIGTERM to process_group={pid}"),
                )
                .await;
            }
            Err(err) => {
                {
                    let mut state = runtime.state.lock().await;
                    state.alive = true;
                    state.last_activity = Instant::now();
                }
                let _ = record_agent_activity(
                    &pool,
                    Some(agent_id),
                    None,
                    "run_error",
                    "Claude warm stream-json idle stop failed",
                    err,
                )
                .await;
            }
        }
        return;
    }
}

fn event_ingest_input_segments_from_context(context: &str) -> Vec<String> {
    context
        .lines()
        .filter_map(|line| {
            line.trim()
                .strip_prefix("- realtime/")
                .map(|path| format!("realtime/{}", path.trim()))
        })
        .filter(|path| path.ends_with(".md"))
        .collect()
}

fn safe_relative_path(root: &Path, relative_path: &str) -> CommandResult<PathBuf> {
    let relative = Path::new(relative_path);
    if relative.is_absolute() {
        return Err("path must be relative".to_owned());
    }
    for component in relative.components() {
        if !matches!(component, Component::Normal(_)) {
            return Err("path cannot escape root".to_owned());
        }
    }
    Ok(root.join(relative))
}

async fn validate_event_ingest_work_item_done(
    pool: &SqlitePool,
    agent_id: Uuid,
    work_item_id: Uuid,
) -> CommandResult<Option<String>> {
    let row = sqlx::query(
        r#"
        select w.source_kind, w.context, a.working_directory
        from agent_work_items w
        join agents a on a.id = w.agent_id
        where w.id = $1 and w.agent_id = $2
        "#,
    )
    .bind(work_item_id)
    .bind(agent_id)
    .fetch_optional(pool)
    .await
    .map_err(to_string)?;
    let Some(row) = row else {
        return Ok(None);
    };
    let source_kind: String = row.get("source_kind");
    if source_kind != "event_ingest" {
        return Ok(None);
    }
    let context: String = row.get("context");
    let working_directory: String = row.get("working_directory");
    let memory_root = PathBuf::from(working_directory.trim()).join("memory");
    let input_segments = event_ingest_input_segments_from_context(&context);
    if input_segments.is_empty() {
        return Ok(Some(
            "event_ingest missing input segments in work item context".to_owned(),
        ));
    }
    for input in input_segments {
        let path = safe_relative_path(&memory_root, &input)?;
        if path.exists() {
            return Ok(Some(format!(
                "event_ingest input segment still exists: {}",
                path.display()
            )));
        }
    }
    let summary_path = memory_root.join("events").join("summary.md");
    let Ok(summary) = fs::read_to_string(&summary_path) else {
        return Ok(Some(format!(
            "event_ingest did not write event summary: {}",
            summary_path.display()
        )));
    };
    if summary.contains("Use this format for each event:")
        && !summary.lines().any(|line| {
            line.trim().starts_with("Summary:") && !line.contains("<merged concise event summary")
        })
    {
        return Ok(Some(format!(
            "event_ingest left event summary scaffold unchanged: {}",
            summary_path.display()
        )));
    }
    Ok(None)
}

async fn finish_warm_claude_active_turn(
    pool: &SqlitePool,
    agent_id: Uuid,
    runtime: &Arc<WarmClaudeRuntime>,
    success: bool,
    error: Option<String>,
) -> CommandResult<()> {
    let (active, session_id) = {
        let mut state = runtime.state.lock().await;
        state.last_activity = Instant::now();
        let active = state.active.take();
        if let Some(active) = active.as_ref() {
            state.last_surface = Some(ClaudeSurface {
                channel_id: active.channel_id,
                thread_root_id: active.thread_root_id,
            });
        }
        let session_id = state.session_id.clone();
        (active, session_id)
    };
    let Some(active) = active else {
        return Ok(());
    };
    let elapsed_ms = active.started_at.elapsed().as_millis();
    let current_work_status: Option<String> = match active.work_item_id {
        Some(work_item_id) => {
            sqlx::query_scalar("select status from agent_work_items where id = $1")
                .bind(work_item_id)
                .fetch_optional(pool)
                .await
                .map_err(to_string)?
        }
        None => None,
    };
    let was_cancelled = current_work_status.as_deref() == Some("cancelling");
    let final_output_text = active.output_text.clone();

    let hidden = if success && !was_cancelled {
        consume_streaming_agent_control_lines(
            pool,
            agent_id,
            active.run_id,
            active.work_item_id,
            &active.stream_key,
        )
        .await?
    } else {
        false
    };
    if !hidden {
        finish_streaming_agent_message(
            pool,
            &active.stream_key,
            if success && !was_cancelled {
                "complete"
            } else {
                "error"
            },
        )
        .await?;
    }

    let run_status = if was_cancelled {
        "cancelled"
    } else if success {
        "exited"
    } else {
        "failed"
    };
    let agent_status = if success || was_cancelled {
        "idle"
    } else {
        "error"
    };
    let log_line = if was_cancelled {
        "claude warm turn cancelled\n".to_owned()
    } else {
        error
            .as_ref()
            .map(|error| format!("claude warm turn failed: {error}\n"))
            .unwrap_or_else(|| format!("claude warm turn completed in {elapsed_ms} ms\n"))
    };
    sqlx::query(
        r#"
        update agent_runs
        set status = $2,
            exit_code = null,
            log = substr(log || $3, -20000),
            stopped_at = strftime('%Y-%m-%dT%H:%M:%f+00:00','now')
        where id = $1
        "#,
    )
    .bind(active.run_id)
    .bind(run_status)
    .bind(&log_line)
    .execute(pool)
    .await
    .map_err(to_string)?;
    notify_ui_agent_run_changed(pool, active.run_id, "claude_turn_finished").await;

    sqlx::query("update agents set status = $2 where id = $1")
        .bind(agent_id)
        .bind(agent_status)
        .execute(pool)
        .await
        .map_err(to_string)?;
    notify_ui_agent_changed(pool, agent_id, "agent_finished").await;

    if let Some(work_item_id) = active.work_item_id {
        let current_work_status: Option<String> =
            sqlx::query_scalar("select status from agent_work_items where id = $1")
                .bind(work_item_id)
                .fetch_optional(pool)
                .await
                .map_err(to_string)?;
        let was_silent = current_work_status.as_deref() == Some("silent");
        let was_interrupted = current_work_status.as_deref() == Some("interrupted");
        let ingest_error = if success && !was_cancelled {
            validate_event_ingest_work_item_done(pool, agent_id, work_item_id).await?
        } else {
            None
        };
        let effective_success = success && ingest_error.is_none();
        let work_status = if was_cancelled {
            "cancelled"
        } else if was_interrupted && effective_success {
            "interrupted"
        } else if was_silent && effective_success {
            "silent"
        } else if effective_success {
            "done"
        } else {
            "failed"
        };
        sqlx::query(
            r#"
            update agent_work_items
            set status = $2,
                result_body = case when trim($3) <> '' then $3 else result_body end,
                completed_at = strftime('%Y-%m-%dT%H:%M:%f+00:00','now'),
                updated_at = strftime('%Y-%m-%dT%H:%M:%f+00:00','now')
            where id = $1
            "#,
        )
        .bind(work_item_id)
        .bind(work_status)
        .bind(if effective_success && !was_cancelled {
            final_output_text.as_str()
        } else {
            ""
        })
        .execute(pool)
        .await
        .map_err(to_string)?;
        mark_task_after_work_item_finished(
            pool,
            work_item_id,
            agent_id,
            active.run_id,
            work_status,
        )
        .await?;
        notify_ui_work_item_changed(pool, work_item_id, "work_item_finished").await;
        record_agent_activity(
            pool,
            Some(agent_id),
            Some(active.run_id),
            "dispatch",
            work_status_title(work_status),
            ingest_error.unwrap_or_else(|| work_item_id.to_string()),
        )
        .await?;
    }

    let provider_thread_id = session_id.unwrap_or_else(|| {
        runtime
            .pid
            .map(|pid| format!("pid:{pid}"))
            .unwrap_or_else(|| "unknown".to_owned())
    });
    upsert_runtime_thread_id(
        pool,
        agent_id,
        "claude",
        &provider_thread_id,
        if success || was_cancelled {
            "idle"
        } else {
            "failed"
        },
    )
    .await?;
    record_agent_activity(
        pool,
        Some(agent_id),
        Some(active.run_id),
        if success || was_cancelled {
            "run"
        } else {
            "run_error"
        },
        if was_cancelled {
            "Stopped"
        } else if success {
            "Completed"
        } else {
            "Failed"
        },
        if success || was_cancelled {
            format!("duration={elapsed_ms} ms")
        } else {
            log_line.trim().to_owned()
        },
    )
    .await?;
    let _ = notify_supervisor_wake(pool).await;
    Ok(())
}

async fn finish_warm_codex_active_turn(
    pool: &SqlitePool,
    agent_id: Uuid,
    runtime: &Arc<WarmCodexRuntime>,
    success: bool,
    error: Option<String>,
) -> CommandResult<()> {
    let active = {
        let mut state = runtime.state.lock().await;
        state.last_activity = Instant::now();
        state.active.take()
    };
    let Some(active) = active else {
        return Ok(());
    };
    let elapsed_ms = active.started_at.elapsed().as_millis();
    let current_work_status: Option<String> = match active.work_item_id {
        Some(work_item_id) => {
            sqlx::query_scalar("select status from agent_work_items where id = $1")
                .bind(work_item_id)
                .fetch_optional(pool)
                .await
                .map_err(to_string)?
        }
        None => None,
    };
    let was_cancelled = current_work_status.as_deref() == Some("cancelling");
    let final_output_text = active.output_text.clone();

    let completed_agent_message_stream_keys = active.completed_agent_message_stream_keys;
    for stream_key in active.stream_keys {
        let hidden = if success && !was_cancelled {
            consume_streaming_agent_control_lines(
                pool,
                agent_id,
                active.run_id,
                active.work_item_id,
                &stream_key,
            )
            .await?
        } else {
            false
        };
        if !hidden {
            if completed_agent_message_stream_keys.contains(&stream_key) {
                finish_streaming_agent_message(pool, &stream_key, "complete").await?;
                dispatch_streaming_agent_message_mentions(pool, &stream_key).await?;
            } else {
                finish_streaming_agent_message(
                    pool,
                    &stream_key,
                    if success && !was_cancelled {
                        "complete"
                    } else {
                        "error"
                    },
                )
                .await?;
            }
        }
    }

    for steer in active.steer_requests.into_values() {
        finish_codex_steer_request(
            pool,
            agent_id,
            steer,
            success && !was_cancelled,
            if was_cancelled {
                Some("cancelled".to_owned())
            } else {
                error.clone()
            },
        )
        .await?;
    }

    let run_status = if was_cancelled {
        "cancelled"
    } else if success {
        "exited"
    } else {
        "failed"
    };
    let agent_status = if success || was_cancelled {
        "idle"
    } else {
        "error"
    };
    let log_line = if was_cancelled {
        "codex warm turn cancelled\n".to_owned()
    } else {
        error
            .as_ref()
            .map(|error| format!("codex warm turn failed: {error}\n"))
            .unwrap_or_else(|| format!("codex warm turn completed in {elapsed_ms} ms\n"))
    };
    sqlx::query(
        r#"
        update agent_runs
        set status = $2,
            exit_code = null,
            log = substr(log || $3, -20000),
            stopped_at = strftime('%Y-%m-%dT%H:%M:%f+00:00','now')
        where id = $1
        "#,
    )
    .bind(active.run_id)
    .bind(run_status)
    .bind(&log_line)
    .execute(pool)
    .await
    .map_err(to_string)?;
    notify_ui_agent_run_changed(pool, active.run_id, "codex_turn_finished").await;

    sqlx::query("update agents set status = $2 where id = $1")
        .bind(agent_id)
        .bind(agent_status)
        .execute(pool)
        .await
        .map_err(to_string)?;
    notify_ui_agent_changed(pool, agent_id, "agent_finished").await;

    if let Some(work_item_id) = active.work_item_id {
        let current_work_status: Option<String> =
            sqlx::query_scalar("select status from agent_work_items where id = $1")
                .bind(work_item_id)
                .fetch_optional(pool)
                .await
                .map_err(to_string)?;
        let was_silent = current_work_status.as_deref() == Some("silent");
        let was_interrupted = current_work_status.as_deref() == Some("interrupted");
        let ingest_error = if success && !was_cancelled {
            validate_event_ingest_work_item_done(pool, agent_id, work_item_id).await?
        } else {
            None
        };
        let effective_success = success && ingest_error.is_none();
        let work_status = if was_cancelled {
            "cancelled"
        } else if was_interrupted && effective_success {
            "interrupted"
        } else if was_silent && effective_success {
            "silent"
        } else if effective_success {
            "done"
        } else {
            "failed"
        };
        sqlx::query(
            r#"
            update agent_work_items
            set status = $2,
                result_body = case when trim($3) <> '' then $3 else result_body end,
                completed_at = strftime('%Y-%m-%dT%H:%M:%f+00:00','now'),
                updated_at = strftime('%Y-%m-%dT%H:%M:%f+00:00','now')
            where id = $1
            "#,
        )
        .bind(work_item_id)
        .bind(work_status)
        .bind(if effective_success && !was_cancelled {
            final_output_text.as_str()
        } else {
            ""
        })
        .execute(pool)
        .await
        .map_err(to_string)?;
        mark_task_after_work_item_finished(
            pool,
            work_item_id,
            agent_id,
            active.run_id,
            work_status,
        )
        .await?;
        notify_ui_work_item_changed(pool, work_item_id, "work_item_finished").await;
        record_agent_activity(
            pool,
            Some(agent_id),
            Some(active.run_id),
            "dispatch",
            work_status_title(work_status),
            ingest_error.unwrap_or_else(|| work_item_id.to_string()),
        )
        .await?;
    }

    upsert_runtime_thread_id(
        pool,
        agent_id,
        "codex",
        &runtime.thread_id,
        if success || was_cancelled {
            "idle"
        } else {
            "failed"
        },
    )
    .await?;
    record_agent_activity(
        pool,
        Some(agent_id),
        Some(active.run_id),
        if success || was_cancelled {
            "run"
        } else {
            "run_error"
        },
        if was_cancelled {
            "Stopped"
        } else if success {
            "Completed"
        } else {
            "Failed"
        },
        if success || was_cancelled {
            format!("duration={elapsed_ms} ms")
        } else {
            log_line.trim().to_owned()
        },
    )
    .await?;
    let _ = notify_supervisor_wake(pool).await;
    Ok(())
}

async fn supervisor_stop_run(
    pool: &SqlitePool,
    codex_registry: &WarmCodexRegistry,
    run_id: Uuid,
) -> CommandResult<()> {
    let row = sqlx::query(
        r#"
        select r.agent_id, r.pid, r.work_item_id, a.runtime
        from agent_runs r
        join agents a on a.id = r.agent_id
        where r.id = $1 and r.stopped_at is null
        "#,
    )
    .bind(run_id)
    .fetch_one(pool)
    .await
    .map_err(to_string)?;

    let agent_id: Uuid = row.get("agent_id");
    let pid: Option<i32> = row.get("pid");
    let work_item_id: Option<Uuid> = row.get("work_item_id");
    let runtime: String = row.get("runtime");
    let Some(pid) = pid else {
        return Err("agent run does not have a pid yet".to_owned());
    };

    sqlx::query("update agent_runs set status = 'stopping' where id = $1")
        .bind(run_id)
        .execute(pool)
        .await
        .map_err(to_string)?;
    notify_ui_agent_run_changed(pool, run_id, "run_stopping").await;
    sqlx::query("update agents set status = 'stopping' where id = $1")
        .bind(agent_id)
        .execute(pool)
        .await
        .map_err(to_string)?;
    notify_ui_agent_changed(pool, agent_id, "agent_stopping").await;
    if let Some(work_item_id) = work_item_id {
        sqlx::query(
            r#"
            update agent_work_items
            set status = 'cancelling',
                updated_at = strftime('%Y-%m-%dT%H:%M:%f+00:00','now')
            where id = $1 and status in ('queued', 'running')
            "#,
        )
        .bind(work_item_id)
        .execute(pool)
        .await
        .map_err(to_string)?;
        notify_ui_work_item_changed(pool, work_item_id, "work_item_cancelling").await;
    }

    if runtime.eq_ignore_ascii_case("codex") {
        let warm_runtime = {
            let runtimes = codex_registry.runtimes.lock().await;
            runtimes.get(&agent_id).cloned()
        };
        if let Some(runtime) = warm_runtime {
            if interrupt_warm_codex_turn(pool, agent_id, &runtime, run_id).await? {
                record_agent_activity(
                    pool,
                    Some(agent_id),
                    Some(run_id),
                    "run",
                    "Stop requested",
                    "Codex accepted stop request",
                )
                .await?;
                return Ok(());
            }
        }
    }

    terminate_process_group(pid).await?;

    append_run_log(
        pool,
        run_id,
        format!("sent SIGTERM to process group {pid}\n"),
    )
    .await?;
    record_agent_activity(
        pool,
        Some(agent_id),
        Some(run_id),
        "run",
        "Stop requested",
        format!("process_group={pid}"),
    )
    .await?;
    Ok(())
}

fn normalize_channel_name(name: &str) -> String {
    name.trim()
        .trim_start_matches('#')
        .to_lowercase()
        .replace(' ', "-")
}

pub(crate) fn to_string(error: impl std::fmt::Display) -> String {
    error.to_string()
}

pub fn run() {
    let database_url = db_url();
    let pool = tauri::async_runtime::block_on(db_connect_with_url(&database_url, 5))
        .expect("failed to connect Lantor SQLite database");

    tauri::async_runtime::block_on(migrate(&pool)).expect("failed to initialize Lantor schema");
    launch_agent::spawn_supervisor_process(&database_url);
    let state_db_url = database_url.clone();
    let reminder_pool = pool.clone();

    tauri::Builder::default()
        .manage(AppState {
            pool,
            db_url: state_db_url,
        })
        .setup(move |app| {
            spawn_ui_refresh_listener(app.handle().clone(), reminder_pool.clone());
            web::spawn_web_server_if_configured(reminder_pool.clone(), database_url.clone());
            spawn_reminder_worker(reminder_pool.clone());
            configure_main_window(app);
            Ok(())
        })
        .invoke_handler(tauri::generate_handler![
            agent_workspace_list,
            agent_workspace_read_file,
            bootstrap,
            artifact_read,
            call_session_start,
            call_session_stop,
            call_session_submit_utterance,
            call_session_submit_text_utterance,
            call_dispatch_cancel_work,
            call_dispatch_resolve_confirmation,
            cancel_agent_work,
            cancel_reminder,
            check_runtime,
            complete_reminder,
            create_agent,
            create_agent_schedule,
            create_channel,
            create_reminder,
            claim_task,
            delete_agent,
            delete_channel,
            delete_message,
            dispatch_agent_work,
            fetch_call_history,
            fetch_messages,
            forward_task,
            install_supervisor_service,
            long_task_approval,
            long_task_approve,
            long_task_create,
            long_task_inspect,
            long_task_list,
            long_task_reject,
            long_task_steer,
            long_task_stop,
            dismiss_inbox_items,
            mark_inbox_items_read,
            mark_all_inbox_read,
            mark_channel_read,
            open_dm_with_agent,
            open_external_url,
            record_ui_refresh_metric,
            reassign_agent_work,
            retry_agent_work,
            request_microphone_permission,
            request_speech_recognition_permission,
            send_message,
            set_message_saved,
            set_message_todo,
            create_todo_item,
            delete_todo_item,
            complete_todo_item,
            set_channel_agent_membership,
            snooze_reminder,
            start_agent,
            stop_agent,
            synthesize_tts_audio,
            tool_browser::close_embedded_tool_browser,
            tool_browser::close_tool_browser,
            tool_browser::focus_tool_browser,
            tool_browser::go_back_embedded_tool_browser,
            tool_browser::go_forward_embedded_tool_browser,
            tool_browser::open_embedded_tool_browser,
            tool_browser::open_tool_browser,
            tool_browser::retarget_tool_browser,
            tool_browser::set_embedded_tool_browser_bounds,
            transcribe_voice_audio,
            uninstall_supervisor_service,
            update_agent,
            update_agent_schedule_status,
            update_channel,
            update_message,
            update_owner_profile,
            update_thread_followed,
            update_task_title,
            update_task_status
        ])
        .run(tauri::generate_context!())
        .expect("error while running Lantor");
}

fn main() {
    let args = env::args().collect::<Vec<_>>();
    if let Some(tool_arg_index) = args.iter().position(|arg| arg == "--agent-context-tool") {
        let tool_args = args
            .get(tool_arg_index + 1..)
            .map(|args| args.to_vec())
            .unwrap_or_default();
        match tauri::async_runtime::block_on(run_agent_context_tool(&tool_args)) {
            Ok(output) => {
                println!("{output}");
                return;
            }
            Err(err) => {
                eprintln!("{err}");
                std::process::exit(1);
            }
        }
    }

    if args.iter().any(|arg| arg == "--supervisor") {
        if let Err(err) = tauri::async_runtime::block_on(run_supervisor()) {
            eprintln!("Lantor supervisor stopped: {err}");
            std::process::exit(1);
        }
    } else {
        run();
    }
}

