    #[test]
    fn ui_refresh_metrics_log_prunes_after_append() {
        let dir = std::env::temp_dir().join(format!("lantor-refresh-metrics-{}", Uuid::new_v4()));
        std_fs::create_dir_all(&dir).expect("create metrics temp dir");
        let database_path = dir.join("lantor.sqlite");
        let log_path = dir.join("ui-refresh-metrics.jsonl");

        let mut existing = String::new();
        for index in 0..4 {
            let entry = json!({
                "logged_at": Utc::now().to_rfc3339(),
                "metric": {
                    "kind": format!("old-{index}"),
                    "payload": "x".repeat(1_200_000),
                },
            });
            existing.push_str(&entry.to_string());
            existing.push('\n');
        }
        assert!(existing.len() < UI_REFRESH_METRICS_MAX_BYTES);
        std_fs::write(&log_path, existing).expect("seed metrics log");

        append_ui_refresh_metrics_log(
            &format!("sqlite://{}", database_path.display()),
            json!({
                "kind": "new",
                "payload": "y".repeat(600_000),
            }),
        )
        .expect("append metrics log");

        let log = std_fs::read_to_string(&log_path).expect("read metrics log");
        assert!(log.len() <= UI_REFRESH_METRICS_MAX_BYTES);
        assert!(log.contains(r#""kind":"new""#));
        assert!(!log.contains(r#""kind":"old-0""#));

        std_fs::remove_dir_all(dir).ok();
    }

