    #[test]
    fn work_item_prompt_preserves_full_call_request_after_inbox_wrapper() {
        let full_request_marker = "keep-this-middle-spoken-detail";
        let full_spoken_request = format!(
            "@Ada implement the rollout {} {full_request_marker} {}",
            "front context ".repeat(300),
            "rear context ".repeat(300)
        );
        let spoken_payload = json!({
            "schema": "lantor.call.spoken_request.v1",
            "encoding": "json_escaped_utf8",
            "inline_budget_chars": 16 * 1024,
            "original_char_length": full_spoken_request.chars().count(),
            "original_byte_length": full_spoken_request.len(),
            "original_sha256": format!("{:x}", sha2::Sha256::digest(full_spoken_request.as_bytes())),
            "truncated": false,
            "included_source_char_budget": full_spoken_request.chars().count(),
            "included_text_char_length": full_spoken_request.chars().count(),
            "text": full_spoken_request,
        });
        let call_context = format!(
            "Call Mode worker brief:\n\
             session_id: {}\n\
             dispatch_id: {}\n\
             utterance_id: {}\n\
             transcript_excerpt:\n\
             {}\n\n\
             spoken_request:\n\
             {}",
            Uuid::new_v4(),
            Uuid::new_v4(),
            Uuid::new_v4(),
            compact_chars_middle(&full_spoken_request, 1024),
            serde_json::to_string_pretty(&spoken_payload).unwrap()
        );
        let inbox_context = prepend_inbox_context(Uuid::new_v4(), "call_mode", &call_context);
        let prompt = build_work_item_prompt(
            Uuid::new_v4(),
            "Call Mode request",
            &inbox_context,
            Some("call-ops"),
            Some("Call Mode dispatch verification"),
            None,
            Some(Uuid::new_v4()),
            &[],
            None,
        );

        assert!(prompt.contains("Agent inbox item:"));
        assert!(prompt.contains("kind: call_mode"));
        assert!(prompt.contains("Call Mode worker brief:"));
        assert!(prompt.contains("spoken_request:"));
        assert!(prompt.contains("lantor.call.spoken_request.v1"));
        assert!(prompt.contains(full_request_marker));
        assert!(prompt.contains("\"truncated\": false"));
    }

