    #[test]
    fn interrupted_action_context_exposes_payload_and_resolution_protocol() {
        let stream_key = format!("{}:item-1", Uuid::new_v4());
        let context = inbox_wake_context(
            &[InboxWakeItem {
                id: Uuid::new_v4(),
                channel_id: Some(Uuid::new_v4()),
                channel_name: Some("coordination".to_owned()),
                channel_description: None,
                channel_kind: Some("channel".to_owned()),
                thread_root_id: Some(Uuid::new_v4()),
                source_message_id: None,
                task_id: None,
                kind: "interrupted_action".to_owned(),
                priority: 95,
                title: "Agent reply needs context refresh".to_owned(),
                body_preview: "stale_context".to_owned(),
                payload: json!({
                    "interrupted_action": "public_reply",
                    "reason": "stale_context",
                    "stream_key": stream_key,
                    "action_kind": "reply_text",
                    "base_version": 1,
                    "current_version": 2,
                    "base_thread_version": 2,
                    "draft_body": "old answer",
                    "allowed_actions": ["revise", "yield", "force_send"],
                    "held_visible_events": [],
                    "arrived_during_composition": [
                        {
                            "sender_name": "Dylan",
                            "sender_role": "owner",
                            "body_preview": "newer room message"
                        }
                    ]
                })
                .to_string(),
                message_created_at: None,
                sender_name: None,
                sender_role: None,
            }],
            &[],
        );

        assert!(context.contains("interrupted_action: agent-only recovery for held public output"));
        assert!(context.contains("decision: resolve this yourself using allowed_actions"));
        assert!(context.contains("do not ask the user to choose"));
        assert!(context.contains("allowed_actions: [\"revise\",\"yield\",\"force_send\"]"));
        assert!(context.contains("draft_body: old answer"));
        assert!(context.contains("arrived_during_composition_count: 1"));
        assert!(context.contains("newer room message"));
        assert!(context.contains("interrupted_action_resolve"));
        assert!(context.contains("the backend provides facts and actions"));
        assert!(context.contains("to stay silent"));
        assert!(context.contains("to revise"));
        assert!(context.contains("then continue with the revised visible reply"));
        assert!(!context.contains("revise is not allowed for this interruption"));
    }

    #[test]
    fn interrupted_action_context_for_side_effect_only_omits_revise_protocol() {
        let stream_key = format!("{}:event-1", Uuid::new_v4());
        let context = inbox_wake_context(
            &[InboxWakeItem {
                id: Uuid::new_v4(),
                channel_id: Some(Uuid::new_v4()),
                channel_name: Some("coordination".to_owned()),
                channel_description: None,
                channel_kind: Some("channel".to_owned()),
                thread_root_id: Some(Uuid::new_v4()),
                source_message_id: None,
                task_id: None,
                kind: "interrupted_action".to_owned(),
                priority: 95,
                title: "Agent reply needs context refresh".to_owned(),
                body_preview: "stale_context".to_owned(),
                payload: json!({
                    "interrupted_action": "visible_control_event",
                    "reason": "stale_context",
                    "stream_key": stream_key,
                    "action_kind": "channel_message_create",
                    "base_version": 1,
                    "current_version": 2,
                    "base_thread_version": 2,
                    "draft_body": "",
                    "allowed_actions": ["yield", "force_send"],
                    "held_visible_events": [
                        "{\"type\":\"channel_message_create\",\"body\":\"queued side effect\"}"
                    ]
                })
                .to_string(),
                message_created_at: None,
                sender_name: None,
                sender_role: None,
            }],
            &[],
        );

        assert!(context.contains("interrupted_action: agent-only recovery for held public output"));
        assert!(context.contains("decision: resolve this yourself using allowed_actions"));
        assert!(context.contains("do not ask the user to choose"));
        assert!(context.contains("allowed_actions: [\"yield\",\"force_send\"]"));
        assert!(context.contains("interrupted_action: visible_control_event"));
        assert!(context.contains("held_visible_events_count: 1"));
        assert!(context.contains("revise is not allowed for this interruption"));
        assert!(context.contains("resolve with yield or force_send yourself"));
        assert!(!context.contains("then continue with the revised visible reply"));
        assert!(!context.contains("\"action\":\"revise\""));
    }

    #[test]
    fn claude_surface_boundary_only_appears_when_surface_changes() {
        let channel_id = Uuid::new_v4();
        let thread_a = Uuid::new_v4();
        let thread_b = Uuid::new_v4();
        let previous = ClaudeSurface {
            channel_id: Some(channel_id),
            thread_root_id: Some(thread_a),
        };

        assert!(claude_surface_boundary_marker(None, previous).is_none());
        assert!(claude_surface_boundary_marker(Some(previous), previous).is_none());

        let marker = claude_surface_boundary_marker(
            Some(previous),
            ClaudeSurface {
                channel_id: Some(channel_id),
                thread_root_id: Some(thread_b),
            },
        )
        .expect("changed surface should produce a boundary");
        assert!(marker.contains("Lantor thread boundary"));
        assert!(marker.contains("Previous surface:"));
        assert!(marker.contains("Current surface:"));
    }

    #[tokio::test]
    async fn thread_context_injects_only_current_thread_messages() {
        let Some((pool, schema)) = test_pool().await else {
            return;
        };
        let result: Result<(), String> = async {
            let channel_id = insert_test_channel(&pool, "claude-context").await?;
            let thread_a: Uuid = sqlx::query_scalar(
                r#"
                insert into messages (channel_id, sender_name, sender_role, body, is_task)
                values ($1, 'Dylan', 'owner', 'thread A root', false)
                returning id
                "#,
            )
            .bind(channel_id)
            .fetch_one(&pool)
            .await
            .map_err(|err| err.to_string())?;
            let thread_b: Uuid = sqlx::query_scalar(
                r#"
                insert into messages (channel_id, sender_name, sender_role, body, is_task)
                values ($1, 'Dylan', 'owner', 'thread B root with forbidden bleed', false)
                returning id
                "#,
            )
            .bind(channel_id)
            .fetch_one(&pool)
            .await
            .map_err(|err| err.to_string())?;
            sqlx::query(
                r#"
                insert into messages (channel_id, thread_root_id, sender_name, sender_role, body, is_task)
                values ($1, $2, 'Agent', 'agent', 'thread A reply evidence', false),
                       ($1, $3, 'Agent', 'agent', 'thread B reply forbidden bleed', false)
                "#,
            )
            .bind(channel_id)
            .bind(thread_a)
            .bind(thread_b)
            .execute(&pool)
            .await
            .map_err(|err| err.to_string())?;

            let context = append_thread_context(
                &pool,
                "Default inbox item: summarize",
                Some(channel_id),
                Some("claude-context"),
                Some(thread_a),
            )
            .await?;
            assert!(context.contains("Current thread context"));
            assert!(context.contains("Use this as current-surface evidence"));
            assert!(context.contains("thread A root"));
            assert!(context.contains("thread A reply evidence"));
            assert!(!context.contains("thread B root with forbidden bleed"));
            assert!(!context.contains("thread B reply forbidden bleed"));
            Ok(())
        }
        .await;
        drop_test_schema(pool, schema).await;
        result.unwrap();
    }

    #[tokio::test]
    async fn thread_context_adds_realtime_older_summary_for_long_threads() {
        let Some((pool, schema)) = test_pool().await else {
            return;
        };
        let result: Result<(), String> = async {
            let channel_id = insert_test_channel(&pool, "long-thread-context").await?;
            let thread_root_id: Uuid = sqlx::query_scalar(
                r#"
                insert into messages (channel_id, sender_name, sender_role, body, is_task, created_at)
                values ($1, 'Dylan', 'owner', 'long thread root goal', false, '2026-01-01T00:00:00.000+00:00')
                returning id
                "#,
            )
            .bind(channel_id)
            .fetch_one(&pool)
            .await
            .map_err(|err| err.to_string())?;

            for index in 1..=16 {
                let created_at = format!("2026-01-01T00:00:{index:02}.000+00:00");
                let body = if index == 4 {
                    "older owner decision should be summarized".to_owned()
                } else if index == 16 {
                    "latest reply should stay in recent context".to_owned()
                } else {
                    format!("thread reply {index}")
                };
                sqlx::query(
                    r#"
                    insert into messages (channel_id, thread_root_id, sender_name, sender_role, body, is_task, created_at)
                    values ($1, $2, $3, $4, $5, false, $6)
                    "#,
                )
                .bind(channel_id)
                .bind(thread_root_id)
                .bind(if index == 4 { "Dylan" } else { "Agent" })
                .bind(if index == 4 { "owner" } else { "agent" })
                .bind(body)
                .bind(created_at)
                .execute(&pool)
                .await
                .map_err(|err| err.to_string())?;
            }

            let context = append_thread_context(
                &pool,
                "Default inbox item: continue",
                Some(channel_id),
                Some("long-thread-context"),
                Some(thread_root_id),
            )
            .await?;
            assert!(context.contains("Realtime older-thread summary"));
            assert!(context.contains("older owner decision should be summarized"));
            assert!(context.contains("latest reply should stay in recent context"));
            assert!(context.contains("long thread root goal"));
            Ok(())
        }
        .await;
        drop_test_schema(pool, schema).await;
        result.unwrap();
    }

    #[tokio::test]
    async fn agent_context_tool_reads_thread_history_and_searches_messages() {
        let Some((pool, schema)) = test_pool().await else {
            return;
        };
        let result: Result<(), String> = async {
            let channel_id = insert_test_channel(&pool, "context-tools").await?;
            let root_id: Uuid = sqlx::query_scalar(
                r#"
                insert into messages (channel_id, sender_name, sender_role, body, is_task)
                values ($1, 'Dylan', 'owner', 'root message with needle', false)
                returning id
                "#,
            )
            .bind(channel_id)
            .fetch_one(&pool)
            .await
            .map_err(|err| err.to_string())?;
            sqlx::query(
                r#"
                insert into messages (channel_id, thread_root_id, sender_name, sender_role, body, is_task)
                values ($1, $2, 'agent', 'agent', 'reply inside thread', false),
                       ($1, null, 'Dylan', 'owner', 'separate root message', false)
                "#,
            )
            .bind(channel_id)
            .bind(root_id)
            .execute(&pool)
            .await
            .map_err(|err| err.to_string())?;
            sqlx::query(
                r#"
                insert into messages (
                    channel_id, thread_root_id, sender_name, sender_role, body, is_task,
                    delivery_state, stream_key
                )
                values ($1, $2, 'agent', 'agent', '', false, 'streaming', 'empty-placeholder')
                "#,
            )
            .bind(channel_id)
            .bind(root_id)
            .execute(&pool)
            .await
            .map_err(|err| err.to_string())?;

            let history_args = vec![
                "history-read".to_owned(),
                "--target".to_owned(),
                format!("#context-tools:{}", short_id(root_id)),
                "--limit".to_owned(),
                "10".to_owned(),
            ];
            let history = agent_context_history_read(&pool, &history_args).await?;
            assert!(history.contains("Lantor history for #context-tools"));
            assert!(history.contains("(2 messages)"));
            assert!(history.contains("root message with needle"));
            assert!(history.contains("reply inside thread"));
            assert!(history.contains("[target=#context-tools:"));
            assert!(history.contains(" type=owner] Dylan: root message with needle"));
            assert!(!history.contains("separate root message"));
            assert!(!history.contains("empty-placeholder"));

            let search_args = vec![
                "message-search".to_owned(),
                "--query".to_owned(),
                "needle".to_owned(),
                "--target".to_owned(),
                "#context-tools".to_owned(),
            ];
            let search = agent_context_message_search(&pool, &search_args).await?;
            assert!(search.contains("root message with needle"));
            assert!(search.contains("[target=#context-tools msg="));
            Ok(())
        }
        .await;
        drop_test_schema(pool, schema).await;
        assert!(result.is_ok(), "{:?}", result.err());
    }

