    #[tokio::test]
    async fn manual_forward_reassigns_queued_task_work() {
        let Some((pool, schema)) = test_pool().await else {
            return;
        };
        let result: Result<(), String> = async {
            let source_agent_id = insert_test_agent(&pool, "forward-source").await?;
            let target_agent_id = insert_test_agent(&pool, "forward-target").await?;
            let channel_id = insert_test_channel(&pool, "task-forward").await?;
            sqlx::query(
                r#"
                insert into channel_members (channel_id, agent_id)
                values ($1, $2)
                "#,
            )
            .bind(channel_id)
            .bind(source_agent_id)
            .execute(&pool)
            .await
            .map_err(|err| err.to_string())?;
            let root_message_id: Uuid = sqlx::query_scalar(
                r#"
                insert into messages (channel_id, sender_name, sender_role, body, is_task)
                values ($1, 'Dylan', 'owner', 'Implement manual forwarding', true)
                returning id
                "#,
            )
            .bind(channel_id)
            .fetch_one(&pool)
            .await
            .map_err(|err| err.to_string())?;
            let task_row = sqlx::query(
                r#"
                insert into tasks (message_id, channel_id, title, status, assignee_agent_id)
                values ($1, $2, 'Implement manual forwarding', 'in_progress', $3)
                returning id, number
                "#,
            )
            .bind(root_message_id)
            .bind(channel_id)
            .bind(source_agent_id)
            .fetch_one(&pool)
            .await
            .map_err(|err| err.to_string())?;
            let task_id: Uuid = task_row.get("id");
            let task_number: i64 = task_row.get("number");
            let old_work_item_id: Uuid = sqlx::query_scalar(
                r#"
                insert into agent_work_items (
                    agent_id, channel_id, thread_root_id, task_id, source_kind, title, context, status
                )
                values ($1, $2, $3, $4, 'task', 'Implement manual forwarding', '', 'queued')
                returning id
                "#,
            )
            .bind(source_agent_id)
            .bind(channel_id)
            .bind(root_message_id)
            .bind(task_id)
            .fetch_one(&pool)
            .await
            .map_err(|err| err.to_string())?;

            forward_task_in_pool(
                &pool,
                task_id,
                target_agent_id,
                false,
                Some("source agent is busy".to_owned()),
            )
            .await?;

            let task = sqlx::query("select status, assignee_agent_id from tasks where id = $1")
                .bind(task_id)
                .fetch_one(&pool)
                .await
                .map_err(|err| err.to_string())?;
            assert_eq!(task.get::<String, _>("status"), "in_progress");
            assert_eq!(
                task.get::<Option<Uuid>, _>("assignee_agent_id"),
                Some(target_agent_id)
            );

            let old_status: String =
                sqlx::query_scalar("select status from agent_work_items where id = $1")
                    .bind(old_work_item_id)
                    .fetch_one(&pool)
                    .await
                    .map_err(|err| err.to_string())?;
            assert_eq!(old_status, "cancelled");

            let inbox = sqlx::query(
                r#"
                select kind, task_id, payload->>'reason' as reason
                from agent_inbox_items
                where agent_id = $1
                order by created_at desc
                limit 1
                "#,
            )
            .bind(target_agent_id)
            .fetch_one(&pool)
            .await
            .map_err(|err| err.to_string())?;
            assert_eq!(inbox.get::<String, _>("kind"), "task_assigned");
            assert_eq!(inbox.get::<Option<Uuid>, _>("task_id"), Some(task_id));
            assert_eq!(
                inbox.get::<Option<String>, _>("reason").as_deref(),
                Some("source agent is busy")
            );

            let system_body: String = sqlx::query_scalar(
                r#"
                select body
                from messages
                where channel_id = $1
                  and thread_root_id = $2
                  and sender_role = 'system'
                  and body like $3
                order by created_at desc
                limit 1
                "#,
            )
            .bind(channel_id)
            .bind(root_message_id)
            .bind(format!("Task #{task_number} forwarded%"))
            .fetch_one(&pool)
            .await
            .map_err(|err| err.to_string())?;
            assert!(system_body.contains("@forward-source"));
            assert!(system_body.contains("@forward-target"));

            let target_work_items: i64 = sqlx::query_scalar(
                "select count(*) from agent_work_items where agent_id = $1 and task_id = $2",
            )
            .bind(target_agent_id)
            .bind(task_id)
            .fetch_one(&pool)
            .await
            .map_err(|err| err.to_string())?;
            assert_eq!(target_work_items, 1);
            Ok(())
        }
        .await;
        drop_test_schema(pool, schema).await;
        assert!(result.is_ok(), "{:?}", result.err());
    }

