    #[test]
    fn demux_buffers_split_control_prefix_without_visible_delta() {
        let mut state = AgentMessageControlDemuxState::default();
        let event = r#"{"type":"activity","title":"Step","detail":"one"}"#;

        let first = demux_agent_message_control_delta(&mut state, "Visible\nL");
        assert_eq!(first.visible_delta, "Visible\n");
        assert!(first.event_jsons.is_empty());

        let second = demux_agent_message_control_delta(&mut state, "ANT");
        assert_eq!(second.visible_delta, "");
        assert!(second.event_jsons.is_empty());

        let third =
            demux_agent_message_control_delta(&mut state, &format!("OR_EVENT {event}\nDone"));
        assert_eq!(third.visible_delta, "Done");
        assert_eq!(third.event_jsons, vec![event.to_owned()]);
    }

