    #[tokio::test]
    async fn agent_collaboration_pauses_after_thread_limit() {
        let Some((pool, schema)) = test_pool().await else {
            return;
        };
        let result: Result<(), String> = async {
            let author_id = insert_test_agent(&pool, "loop-author").await?;
            let reviewer_id = insert_test_agent(&pool, "loop-reviewer").await?;
            let channel_id = insert_test_channel(&pool, "loop-guard").await?;
            sqlx::query(
                r#"
                insert into channel_members (channel_id, agent_id)
                values ($1, $2), ($1, $3)
                "#,
            )
            .bind(channel_id)
            .bind(author_id)
            .bind(reviewer_id)
            .execute(&pool)
            .await
            .map_err(|err| err.to_string())?;

            let root_id: Uuid = sqlx::query_scalar(
                r#"
                insert into messages (channel_id, sender_name, sender_role, body, is_task)
                values ($1, 'Dylan', 'owner', 'start collaboration', false)
                returning id
                "#,
            )
            .bind(channel_id)
            .fetch_one(&pool)
            .await
            .map_err(|err| err.to_string())?;
            for index in 0..10 {
                insert_agent_message(
                    &pool,
                    author_id,
                    channel_id,
                    Some(root_id),
                    &format!("agent loop message {index}"),
                    false,
                )
                .await?;
            }
            let system_messages_before_final: i64 = sqlx::query_scalar(
                r#"
                select count(*)
                from messages
                where channel_id = $1
                  and thread_root_id = $2
                  and sender_role = 'system'
                  and body like 'Inter-agent collaboration paused:%'
                "#,
            )
            .bind(channel_id)
            .bind(root_id)
            .fetch_one(&pool)
            .await
            .map_err(|err| err.to_string())?;

            let final_message_id = insert_agent_message(
                &pool,
                author_id,
                channel_id,
                Some(root_id),
                "@loop-reviewer continue the loop",
                false,
            )
            .await?;

            let work_items: i64 = sqlx::query_scalar(
                r#"
                select count(*)
                from agent_work_items
                where channel_id = $1
                  and agent_id = $2
                  and source_message_id = $3
                "#,
            )
            .bind(channel_id)
            .bind(reviewer_id)
            .bind(final_message_id)
            .fetch_one(&pool)
            .await
            .map_err(|err| err.to_string())?;
            assert_eq!(work_items, 0);
            let system_messages: i64 = sqlx::query_scalar(
                r#"
                select count(*)
                from messages
                where channel_id = $1
                  and thread_root_id = $2
                  and sender_role = 'system'
                  and body like 'Inter-agent collaboration paused:%'
                "#,
            )
            .bind(channel_id)
            .bind(root_id)
            .fetch_one(&pool)
            .await
            .map_err(|err| err.to_string())?;
            assert_eq!(system_messages, system_messages_before_final + 1);
            Ok(())
        }
        .await;
        drop_test_schema(pool, schema).await;
        assert!(result.is_ok(), "{:?}", result.err());
    }

